    "dist.kg_tag": "Windows Keygen Tool",
    "dist.kg_title": "Windows 激活码生成器（LubitSoftKeygen）介绍",
    "dist.kg_desc": "LubitSoftKeygen 是专为官方授权分销商打造的 Windows 桌面端正版激活码签发工具，采用现代加密签名技术与高 DPI 原生界面设计，兼顾安全性与出码效率。",
