    "dist.k1_d": "基于 Ed25519 椭圆曲线签名与设备机器码精确绑定，生成的激活码不可伪造、不可篡改，确保正版验证安全可靠。",
    "dist.k2_t": "🖥️ 原生高 DPI 桌面界面",
    "dist.k2_d": "基于 PySide6 构建的轻量级 Windows 桌面客户端，支持深色/浅色主题与高分辨率屏幕清晰显示，输入机器码与选择期限即可出码。",
    "dist.k3_t": "🔒 口令校验与单机设备锁定",
    "dist.k3_d": "内置 PBKDF2-HMAC-SHA512 高强度口令保护及分销商单机设备绑定机制，防止生成器外泄与未授权使用。",
    "dist.k4_t": "📜 完整出码历史与审计记录",
    "dist.k4_d": "自动记录每次激活码生成时间、对应机器码及授权时长，方便分销商对账管理与客户售后查询。",
