    "about.banner_d": "以工程匠心重塑日常软件体验，专注于轻量、纯净的 Android 与 Windows 实用工具研发。",
    "about.story_tag": "Our Story & Mission",
    "about.story_t": "让卓越软件回归纯净",
    "about.story_p1": "LubitSoft 是一家专注于研发高品质 Android 与 Windows 实用工具软件的独立科技品牌。我们热爱简洁直观的交互设计与稳健的系统底层技术。",
    "about.story_p2": "在软件日益臃肿的今天，LubitSoft 始终坚持“Light, Unified, Bit-perfect”（轻盈、统一、精微）的产品哲学，打造零广告、零冗余、隐私优先的工具应用。",
    "about.logo_t": "LubitSoft 品牌标识释义",
    "about.logo_d": "图形标志以几何棱角 “L” 象征稳健的软件底座，右上角跃动的青蓝色数字方格代表灵动的 “Bit（比特）” 创新单元，传达清爽、简洁、可信赖的科技感。",
