    "ch.overview": "Software Overview",
    "ch.overview_t": "软件简介与核心特性",
    "pd.sub": "纯净极简的 Android 设备硬件仪表盘、库仑计电池健康监测与全尺寸桌面微件套件。零广告、零后台唤醒，让您全面掌控爱机状态。",
    "pd.meta1": "版本：v2.1.0",
    "pd.meta2": "包名：com.weijielu.puredasher",
    "pd.meta3": "系统要求：Android 8.0+ (API 26+)",
    "pd.meta4": "授权：免费正版",
    "pd.dl_btn": "⬇ 官方直链 APK 下载 (2.05 MB)",
    "pd.desc": "PureDasher 采用原生 Kotlin 与 Jetpack Compose 倾力打造，专为追求极致轻盈与透明掌控感的 Android 用户设计。软件集成了精密的电池库仑计健康监测服务、一站式设备状态中心以及五种桌面微件，所有核心数据均在设备本地实时演算呈现。",
    "pd.f1_t": "🔋 电池健康库仑计监测",
    "pd.f1_d": "内置轻量级前台监测服务，精确追踪充放电电流、电池温度、循环健康度与预估续航，支持自定义充电保护提醒。",
    "pd.f2_t": "🧩 5 种比例桌面微件矩阵",
    "pd.f2_d": "原生提供 2×1 极简胶囊、2×2 紧凑方格、4×1 极简横条、4×2 详细仪表盘与 4×3 全景监控面板，完美适配各类桌面布局。",
    "pd.f3_t": "🛡️ 透明设备权限中心",
    "pd.f3_d": "清晰展示网络、定位、通知及电池优化状态，支持一键直达系统设置开启或关闭可选进阶权限，绝不强制索权。",
    "pd.f4_t": "🌐 轻量化多语言引擎",
    "pd.f4_d": "支持在线多语言包即时切换与 Material 3 动态取色主题，安装包小巧纯净，无任何第三方广告 SDK。",
    "ac.sub": "航空航电风格的精准数字罗盘、全屏人工地平仪（姿态仪）与实时 GPS / 气压传感遥测应用，为飞行爱好者、户外探险与专业用户打造。",
    "ac.meta1": "版本：v2.2.0",
    "ac.meta2": "包名：com.weijielu.aircompass",
    "ac.meta3": "系统要求：Android 8.0+ (API 26+)",
    "ac.meta4": "授权：免费正版",
    "ac.dl_btn": "⬇ 官方直链 APK 下载 (8.20 MB)",
    "ac.desc": "AirCompass 以现代民航客机主飞行显示器（PFD）为设计灵感，采用 Jetpack Compose 打造丝滑高帧率航空仪表界面。应用融合设备磁力计、加速度计、陀螺仪、气压计与 GPS 定位数据，在离线状态下即可提供高精度航向、俯仰滚转姿态与海拔遥测。",
    "ac.f1_t": "✈️ 全屏人工地平仪 (Artificial Horizon)",
    "ac.f1_d": "高对比度天地线与俯仰角/滚转角刻度盘，支持全屏沉浸式飞行姿态显示与零延迟传感器平滑滤波。",
    "ac.f2_t": "🧭 航空级精准数字罗盘",
    "ac.f2_d": "实时输出真北/磁北航向角度、方位角读数与磁场强度提示，辅助户外导航与方位校准。",
    "ac.f3_t": "📡 GPS 与气压高度遥测",
    "ac.f3_d": "精确显示当前经纬度坐标、海拔高度、地面速度及网络辅助地理信息，支持离线核心计算。",
    "ac.f4_t": "🌍 国际化多语言支持",
    "ac.f4_d": "内置实时多语言翻译引擎，界面清爽专业、无广告干扰，严格遵循 Google Play 隐私与安全规范。",
