    "dino.sub": "彩色高清拟真版恐龙与载具横版跑酷游戏。涵盖 7 大动态生态地图、列车车顶跑酷、4 种角色与真实载具引擎音效、朝霞晚霞与雨雪天气平滑过渡，支持横竖屏无缝畅玩。",
    "dino.meta1": "版本：v1.4.0",
    "dino.meta2": "包名：com.dinohd.game",
    "dino.meta3": "系统要求：Android 7.0+ (API 24+)",
    "dino.meta4": "授权：免费正版 · 零广告",
    "dino.dl_btn": "⬇ 官方直链 APK 下载 (3.29 MB)",
    "dino.desc": "Dino HD 传承经典离线小恐龙跑酷核心手感，并采用原生 Kotlin 高帧率渲染引擎全面重制为彩色高清拟真画面。游戏内置 7 大生态地图、昼夜朝霞晚霞与雨雪动态天气平滑过渡、可跳上车顶奔跑的超长铁路列车、4 种可选角色载具与真实物理合成音效，完全离线运行、零广告干扰。",
    "dino.f1_t": "🌍 7 大拟真地图与列车车顶跑酷",
    "dino.f1_d": "支持沙漠、温带现代城市、热带雨林、苏联雪地、北美沼泽、非洲草原（长颈鹿腿下穿行）与铁路地图（可跳上超长货运集装箱列车与高速客运列车车顶前进）。",
    "dino.f2_t": "🏍️ 4 种角色造型与真实载具音效",
    "dino.f2_d": "自由切换默认小恐龙、全避震山地自行车（真实塔基棘轮与链条声）、450cc 越野摩托车（真实四冲程排气声浪与轰油门音效）及碳纤维弹跳鞋人物。",
    "dino.f3_t": "🌅 朝霞晚霞、2:1 昼夜与天气平滑过渡",
    "dino.f3_d": "提供日出朝霞、正午晴空、日落晚霞、星夜弯月以及晴天、雨天、雪天连续插值平滑过渡，光影层次细腻真实。",
    "dino.f4_t": "🤖 智能轨迹自动模式、无敌模式与金币钱包",
