    "p2048.meta": "应用包名：com.lubitsoft.game2048 · 开发者：LubitSoft Inc. · 更新日期：2026-11-19",
    "p2048.h1": "1. 引言与适用范围",
    "p2048.p1": "LubitSoft 高度重视用户的隐私与数据安全。本隐私权政策适用于您通过 LubitSoft 官方网站、LubitSoft 官方应用中心 App 或其他官方渠道下载并使用的 2048（包名：com.lubitsoft.game2048）Android 游戏应用程序。",
    "p2048.h2": "2. 零敏感权限与纯本地运行架构",
    "p2048.p2": "2048 严格遵循“零敏感权限、100% 本地运行、零隐私上传”原则：",
    "p2048.li1": "零设备敏感权限：本游戏不申请摄像头、麦克风、位置信息、通讯录、电话状态或外部存储读取等任何敏感权限。",
    "p2048.li2": "纯本地游戏存档：您的当前棋盘进度、历史最高分、对局历史记录、游戏时长、音效与多语言设置均 100% 存储在您设备本地的应用沙盒（SharedPreferences）中，绝不上传至任何外部服务器。",
    "p2048.li3": "本地实时音效：游戏内的轻敲音效均在设备本地内存中实时合成播放，不读取或访问您设备上的任何个人媒体文件。",
    "p2048.h3": "3. 零广告与零第三方数据共享承诺",
    "p2048.li4": "2048 无需注册或登录账号，不收集姓名、邮箱、设备标识符（IMEI / OAID / AAID）或任何个人身份信息。",
    "p2048.li5": "本游戏不包含任何第三方商业广告 SDK、统计追踪 SDK 或后台唤醒服务，绝不向任何第三方出售、出租或共享用户数据。",
    "p2048.li6": "外部跳转说明：仅当您在游戏设置中主动点击“公司官网 (lubitsoft.com)”或“问题反馈 (support@lubitsoft.com)”时，系统才会调用您设备上的浏览器或邮件客户端。",
    "p2048.h4": "4. 联系我们",
    "g2048.sub": "LubitSoft 匠心打造的经典数字益智游戏。支持 4×4 至 8×8 多种棋盘、无尽模式与尊贵流光紫高阶方块、双拟真点阵 LED 计时与滚动屏、Expectimax 智能提示与最高 512 倍速自动通关，原生适配 12 种语言与全面屏。",
