    "g2048.desc": "2048 由 LubitSoft 原生打造，在经典滑动合成玩法基础上全面升级：提供 4×4 至 8×8 五档棋盘、无尽模式与 4096+ 分级流光紫罗兰渐变方块、双路硬件级点阵 LED 显示屏（99天精准计时 + 橘黄色逐列步进滚动时间屏）、完整历史对局战绩记录、统一质感轻敲音效以及 12 种语言本地化支持。",
