    "g2048.f2_t": "🤖 Expectimax AI 智能提示与 512 倍速托管",
    "g2048.f2_d": "内置 Expectimax 搜索算法提供最佳走法提示与理由，支持 1x–512x 与「拟真真人思考」速度自动通关，并可在设置中隐藏主界面 AI 按钮。",
    "g2048.f3_t": "📟 双路拟真低像素点阵 LED 显示屏",
    "g2048.f3_d": "配备 99 天级绿色点阵计时器（D 与冒号同步闪烁）与橘黄色逐列步进滚动日期/星期/时间显示屏，退出游戏自动保存并暂停计时。",
    "g2048.f4_t": "🏆 历史战绩追踪与 12 国语言支持",
    "g2048.f4_d": "点击历史最高分即可查看每局得分、用时、起止时间、模式及 AI/提示使用次数；全面适配 12 种语言、挖孔屏安全区与统一轻敲音效。",
    "g2048.cl_v1_t": "v2.0.0 · 安装包大小：5.21 MB",
