    "pay.step_note": "請使用對應 App 掃描上方收款碼完成人民幣支付（月卡 ¥3 / 季卡 ¥5 / 年卡 ¥10 / 永久 ¥20）。支付成功後，請將以下 4 項資訊發送至 <strong>payment@lubitsoft.com</strong> 申請啟用碼：<br>1. 付款截圖<br>2. 交易單號<br>3. 購買的啟用時長（月卡 / 季卡 / 年卡 / 永久啟用）<br>4. 軟體提供的機器碼<br>我們會在 <strong>24 小時內</strong> 處理您的購買申請，並將啟用碼發送至您的買家信箱。",
    "ppd.meta": "套件名稱：com.weijielu.puredasher · 開發者：LubitSoft Inc. · 更新日期：2026-11-18",
    "ppd.h1": "1. 引言與適用範圍",
    "ppd.p1": "LubitSoft 非常重視使用者的隱私與個人數據安全。本隱私權政策適用於您透過 Google Play 或 LubitSoft 官方網站下載並使用的 PureDasher（套件名稱：com.weijielu.puredasher）Android 應用程式及桌面微件服務。",
    "ppd.h2": "2. 權限與本地數據處理",
    "ppd.p2": "PureDasher 堅持「本地優先、最小權限、零隱私上傳」原則：",
    "ppd.li1": "網路與 Wi-Fi 狀態（INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE）：用於在本地顯示網路狀態及切換語言包。",
    "ppd.li2": "電池健康監測（FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS）：用於在本地持續記錄電池庫侖計健康與充放電數據。",
    "ppd.li3": "位置權限（ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION，可選）：僅用於部分 Android 系統讀取本地 Wi-Fi 資訊，絕不背景追蹤或上傳位置軌跡。",
    "ppd.li4": "應用使用統計（PACKAGE_USAGE_STATS，可選）：僅在使用者手動授權後於本機展示應用功耗統計。",
    "ppd.li5": "通知權限（POST_NOTIFICATIONS，可選）：用於發送本地電池健康提醒。",
    "ppd.h3": "3. 數據儲存與共享承諾",
    "ppd.li6": "所有硬體與電池數據僅保存於裝置本地沙盒，絕不出售、出租或共享給任何第三方。",
    "ppd.li7": "本應用不含任何第三方商業廣告 SDK。",
    "ppd.h4": "4. 聯繫我們",
    "pac.meta": "套件名稱：com.weijielu.aircompass · 開發者：LubitSoft Inc. · 更新日期：2026-11-18",
    "pac.h1": "1. 引言與適用範圍",
    "pac.p1": "LubitSoft 高度重視您的個人隱私與位置資訊安全。本隱私權政策適用於 AirCompass（套件名稱：com.weijielu.aircompass）Android 應用程式。",
    "pac.h2": "2. 感測器與權限說明",
    "pac.li1": "位置權限（ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION）：僅用於在您使用應用時即時顯示當前經緯度、海拔、速度及計算磁偏角，絕不進行背景靜默定位或上傳伺服器。",
    "pac.li2": "裝置運動與環境感測器：磁力計、加速度計、陀螺儀與氣壓計數據 100% 在本地用於驅動人工地平儀與羅盤。",
    "pac.li3": "網路權限（INTERNET / ACCESS_NETWORK_STATE）：用於檢查網路狀態及主動切換語言等必要請求。",
    "pac.h3": "3. 零個人數據收集與共享",
    "pac.li4": "AirCompass 無需註冊帳號，不收集姓名、手機號或廣告識別碼（AAID）。",
    "pac.li5": "絕不出售、出租或共享任何使用者數據。",
    "pac.h4": "4. 聯繫我們",
