    "win.banner_title": "Windows 軟體專欄",
    "win.banner_desc": "面向 Windows 桌面平台的高效系統與實用工具，涵蓋完全免費的 LubitSoft Uninstaller、HardwareLens 與 ForceUninstaller。",
    "win.search_ph": "搜尋 Windows 軟體...",
    "hl.sub": "現代化的 Windows 硬體裝置資訊檢測與即時監控工具，全面支援 Windows 10 與 Windows 11。",
    "hl.meta1": "版本：v1.0.0",
    "hl.meta2": "系統要求：Windows 10 / Windows 11",
    "hl.meta3": "安裝包：HardwareLens_Setup_v1.0.0.exe",
    "hl.meta4": "大小：54.82 MB",
    "hl.dl_btn": "⬇ 下載安裝程式 (54.82 MB)",
    "hl.desc": "HardwareLens（硬體視界）是一款面向 Windows 10 與 Windows 11 的現代化硬體裝置資訊檢測與即時監控工具。內建即時效能環形儀表板，全面採集 CPU、記憶體、顯示卡、儲存裝置、主機板 BIOS、網路介面卡與電池健康狀態，支援深淺雙主題與一鍵匯出硬體報告。",
    "hl.f1_t": "📊 即時系統概覽儀表板",
    "hl.f1_d": "即時展示 CPU、記憶體、磁碟使用率環形儀表板與網路吞吐量，核心硬體摘要一目了然。",
    "hl.f2_t": "🔍 全面硬體深度採集",
    "hl.f2_d": "精準識別處理器快取、記憶體條頻率、獨立/整合顯示卡、實體硬碟健康度及主機板 SMBIOS 資訊。",
    "hl.f3_t": "🎨 現代化深淺雙主題",
    "hl.f3_d": "支援淺色與深色主題一鍵切換，支援關鍵字搜尋過濾與屬性值點擊複製。",
    "hl.f4_t": "📄 一鍵匯出硬體報告",
    "hl.f4_d": "支援將完整本機硬體檢測報告一鍵匯出為 JSON、Markdown 或 TXT 格式。",
    "fu.sub": "輕量高效的 Windows 強力卸載與系統殘留深度清理工具，基礎功能免費，部分進階功能收費，支援 Windows 10 與 Windows 11。",
    "fu.meta1": "版本：v1.1.0",
    "fu.meta2": "系統要求：Windows 10 / Windows 11",
    "fu.meta3": "安裝包：ForceUninstaller_Setup_v1.1.0.exe",
    "fu.meta4": "大小：16.53 MB",
    "fu.meta5": "授權：基礎免費 · 部分功能收費",
    "fu.badge_freemium": "部分功能付費",
    "fu.pay_title": "ForceUninstaller 進階功能啟動碼購買",
    "fu.taobao_modal_desc": "淘寶官方店鋪正在籌備上線中，即將開放，敬請期待！目前您可透過微信或支付寶管道購買 ForceUninstaller 進階功能啟動碼。",
    "fu.dl_btn": "⬇ 下載安裝程式 (16.53 MB)",
    "fu.desc": "ForceUninstaller 是一款專為 Windows 10 與 Windows 11 打造的輕量強力軟體卸載工具。單個軟體強力卸載與殘留清理等基礎功能免費開放；「遷移至其他磁碟機」與「選取多個軟體同時卸載」為軟體內付費功能，購買啟動碼即可解鎖完整體驗。",
    "fu.f1_t": "🧹 強力卸載頑固軟體",
    "fu.f1_d": "支援強制終止佔用處理程序並徹底卸載常規方式無法移除的頑固軟體。",
    "fu.f2_t": "🗂️ 殘留檔案與登錄檔清理",
    "fu.f2_d": "卸載後智慧掃描磁碟殘留目錄與 Windows 登錄檔冗餘鍵值，一鍵徹底清除。",
    "fu.f3_t": "⚡ 高 DPI 原生介面",
    "fu.f3_d": "支援高解析度螢幕清晰顯示與自動管理員權限提權，操作直覺流暢。",
    "fu.f4_t": "💎 進階付費功能（Pro 解鎖）",
    "fu.f4_d": "「遷移至其他磁碟機」與「選取多個軟體同時卸載」為軟體內付費功能，購買啟動碼即可解鎖。",
    "fu.paid_section_t": "免費與付費功能說明",
    "fu.paid_section_desc": "ForceUninstaller 的單個軟體強力卸載與殘留清理功能可免費使用；以下兩項進階功能為軟體內收費功能，需購買啟動碼解鎖：",
    "fu.paid_f1_t": "📦 遷移至其他磁碟機（付費功能）",
    "fu.paid_f1_d": "安全將已安裝軟體遷移至其他磁碟分割區，有效釋放系統碟（C 槽）空間，免去重裝煩惱。",
    "fu.paid_f2_t": "☑️ 選取多個軟體同時卸載（付費功能）",
    "fu.paid_f2_d": "支援勾選多個目標軟體一鍵批次強力卸載，並同步清理各自殘留檔案與登錄檔項目。",
    "fu.t_basic": "基礎功能（單個強力卸載 / 殘留清理）",
