    "dist.adv_desc": "成為 LubitSoft 授權經銷商，只需一次性買斷 Windows 啟動碼生成器授權，即可獨立銷售啟動碼，全部銷售利潤歸您所有。",
    "dist.a1_t": "💰 一次性買斷 · 零分成抽佣",
    "dist.a1_d": "僅需 ¥8,000 人民幣一次性買斷授權，無後續年費、無單筆抽成，簽發的每一枚啟動碼收益 100% 歸經銷商所有。",
    "dist.a2_t": "🔑 自主簽發全期限啟動碼",
    "dist.a2_d": "支援生成 1 小時試用、月卡（30 天）、季卡（90 天）、年卡（365 天）及永久啟動碼，靈活制定銷售方案。",
    "dist.a3_t": "⚡ 本機秒級出碼 · 即時交付",
    "dist.a3_d": "無需等待人工審核或上游發貨，在經銷商本機輸入客戶機器碼即可即時生成正版啟動碼。",
    "dist.a4_t": "🛡️ 全線 Windows 軟體通用",
    "dist.a4_d": "支援 HardwareLens 與 ForceUninstaller Pro 等 LubitSoft Windows 付費產品授權體系，並享官方商務與技術支援。",
    "dist.kg_tag": "Windows Keygen Tool",
    "dist.kg_title": "Windows 啟動碼生成器（LubitSoftKeygen）介紹",
    "dist.kg_desc": "LubitSoftKeygen 是專為官方授權經銷商打造的 Windows 桌面端正版啟動碼簽發工具，採用現代加密簽名技術與高 DPI 原生介面。",
    "dist.k1_t": "🔐 Ed25519 非對稱數位簽名",
    "dist.k1_d": "基於 Ed25519 橢圓曲線簽名與設備機器碼精確綁定，生成的啟動碼不可偽造、不可竄改。",
    "dist.k2_t": "🖥️ 原生高 DPI 桌面介面",
    "dist.k2_d": "基於 PySide6 構建的輕量級 Windows 桌面客戶端，支援深淺雙主題與高解析度螢幕清晰顯示。",
    "dist.k3_t": "🔒 口令校驗與單機設備鎖定",
    "dist.k3_d": "內建 PBKDF2-HMAC-SHA512 高強度口令保護及經銷商單機設備綁定機制，防止生成器外洩與未授權使用。",
    "dist.k4_t": "📜 完整出碼歷史與稽核紀錄",
    "dist.k4_d": "自動記錄每次啟動碼生成時間、對應機器碼及授權時長，方便經銷商對帳管理。",
    "dist.buy_tag": "Buyout & Cooperation",
