    "dist.plan_name": "Windows 啟動碼生成器（LubitSoftKeygen）一次性買斷授權",
    "dist.buy_note": "<strong>買斷說明：</strong>經銷商授權僅支援<strong>一次性買斷（¥8,000 人民幣）</strong>。點擊下方「微信 / 支付寶付款」完成支付後，請將付款截圖、交易單號及聯絡方式發送至 <strong>business@lubitsoft.com</strong>，我們將在 <strong>24 小時內</strong> 交付軟體及專屬授權密碼。",
    "dist.pay_title": "經銷商授權買斷付款（¥8,000）",
