    "sup.fee_tag": "Pricing Policy",
    "sup.fee_title": "軟體收費說明",
    "sup.fee_free_t": "免費軟體",
    "sup.fee_free_d": "PureDasher（Android）、AirCompass（Android）、ForceUninstaller（Windows）均提供免費使用，零廣告無捆綁。",
    "sup.fee_paid_t": "付費軟體（HardwareLens）",
    "sup.fee_paid_d": "新使用者提供 1 小時免費試用；付費方案：月卡 ¥3 / 季卡 ¥5 / 年卡 ¥10 / 永久啟用 ¥20（支援微信、支付寶人民幣收款，淘寶官方店鋪即將開放）。",
    "sup.pol_tag": "Service Policy",
    "sup.pol_title": "售後服務支援政策",
    "sup.pol_1_t": "1. 回應時效",
    "sup.pol_1_d": "所有寄送至 Support@LubitSoft.com 或 Service@LubitSoft.com 的郵件，我們均會在 24 小時內處理並回覆。",
    "sup.pol_2_t": "2. 啟用碼交付與找回",
    "sup.pol_2_d": "付款後 24 小時內發送啟用碼至買家信箱。若因重灌系統需核實或補發啟用碼，請提供原付款紀錄聯繫 Service@LubitSoft.com。",
    "sup.pol_3_t": "3. 試用與退款說明",
    "sup.pol_3_d": "付費軟體提供 1 小時免費試用，建議確認相容後再購買。如遇軟體無法運行或重複付款，購買 7 天內可聯繫 Service@LubitSoft.com 申請全額退款；啟用碼一經正常使用，非功能故障原則上不支援無理由退款。",
    "sup.pol_4_t": "4. 版本更新與維護",
    "sup.pol_4_d": "持續提供系統相容性適配與問題修復，授權有效期內均可免費升級同系列小版本更新。",
    "win.empty_t": "Windows 軟體專欄即將上線",
    "win.empty_d": "目前官網已優先開放 Android 端兩款核心應用（PureDasher 與 AirCompass）的官方下載與服務，Windows 桌面軟體正在籌備發布中。",
    "win.empty_btn": "前往 Android 軟體專欄",
    "about.banner_t": "關於 LubitSoft",
    "about.banner_d": "以工程匠心重塑日常軟體體驗，專注於輕量、純淨的 Android 與 Windows 實用工具研發。",
    "about.story_tag": "Our Story & Mission",
    "about.story_t": "讓卓越軟體回歸純淨",
    "about.story_p1": "LubitSoft 是一家專注於研發高品質 Android 與 Windows 實用工具軟體的獨立科技品牌。我們熱愛簡潔直觀的互動設計與穩健的系統底層技術。",
    "about.story_p2": "在軟體日益臃腫的今天，LubitSoft 始終堅持「Light, Unified, Bit-perfect」（輕盈、統一、精微）的產品哲學，打造零廣告、零冗餘、隱私優先的工具應用。",
    "about.logo_t": "LubitSoft 品牌標識釋義",
    "about.logo_d": "圖形標誌以幾何稜角 “L” 象徵穩健的軟體底座，右上角躍動的青藍色數位方格代表靈動的 “Bit（位元）” 創新單元，傳達清爽、簡潔、可信賴的科技感。",
    "about.ms_tag": "Development Roadmap",
    "about.ms_t": "產品演進歷程",
    "about.ms1_t": "確立輕量化理念",
    "about.ms1_d": "確立「零廣告、本地優先、原生性能」的跨平台軟體研發準則。",
    "about.ms2_t": "PureDasher 研發",
    "about.ms2_d": "基於 Jetpack Compose 打造純正 Android 裝置儀表板與五尺寸桌面微件矩陣。",
    "about.ms3_t": "AirCompass 發布",
    "about.ms3_d": "推出航電風格全螢幕人工地平儀與高精度感測器羅盤，並上線 Google Play。",
    "about.ms4_t": "官網多語與桌面端規劃",
    "about.ms4_d": "全面上線 8 國語言官網與真實 APK 直鏈分發，並啟動 Windows 桌面工具研發。",
    "about.ct_tag": "Contact Us",
