    "ch.overview": "Software Overview",
    "ch.overview_t": "軟體簡介與核心特性",
    "pd.sub": "純淨極簡的 Android 裝置硬體儀表板、庫侖計電池健康監測與全尺寸桌面微件套件。零廣告、零背景喚醒，讓您全面掌控愛機狀態。",
    "pd.meta1": "版本：v2.1.0",
    "pd.meta2": "套件名稱：com.weijielu.puredasher",
    "pd.meta3": "系統要求：Android 8.0+ (API 26+)",
    "pd.meta4": "授權：免費正版",
    "pd.dl_btn": "⬇ 官方直鏈 APK 下載 (2.05 MB)",
    "pd.desc": "PureDasher 採用原生 Kotlin 與 Jetpack Compose 傾力打造，專為追求極致輕盈與透明掌控感的 Android 使用者設計。軟體整合了精密的電池庫侖計健康監測服務、一站式裝置狀態中心以及五種桌面微件，所有核心數據均在裝置本地即時演算呈現。",
    "pd.f1_t": "🔋 電池健康庫侖計監測",
    "pd.f1_d": "內建輕量級前景監測服務，精確追蹤充放電電流、電池溫度、循環健康度與預估續航，支援自訂充電保護提醒。",
    "pd.f2_t": "🧩 5 種比例桌面微件矩陣",
    "pd.f2_d": "原生提供 2×1 極簡膠囊、2×2 緊湊方格、4×1 極簡橫條、4×2 詳細儀表板與 4×3 全景監控面板，完美適配各類桌面佈局。",
    "pd.f3_t": "🛡️ 透明裝置權限中心",
    "pd.f3_d": "清晰展示網路、定位、通知及電池最佳化狀態，支援一鍵直達系統設定開啟或關閉可選進階權限，絕不強制索權。",
    "pd.f4_t": "🌐 輕量化多語言引擎",
    "pd.f4_d": "支援線上多語言包即時切換與 Material 3 動態取色主題，安裝包小巧純淨，無任何第三方廣告 SDK。",
    "ac.sub": "航空航電風格的精準數位羅盤、全螢幕人工地平儀（姿態儀）與即時 GPS / 氣壓感測遙測應用，為飛行愛好者、戶外探險與專業使用者打造。",
    "ac.meta1": "版本：v2.2.0",
    "ac.meta2": "套件名稱：com.weijielu.aircompass",
    "ac.meta3": "系統要求：Android 8.0+ (API 26+)",
    "ac.meta4": "授權：免費正版",
    "ac.dl_btn": "⬇ 官方直鏈 APK 下載 (8.20 MB)",
    "ac.desc": "AirCompass 以現代民航客機主飛行顯示器（PFD）為設計靈感，採用 Jetpack Compose 打造絲滑高幀率航空儀表介面。應用融合裝置磁力計、加速度計、陀螺儀、氣壓計與 GPS 定位數據，在離線狀態下即可提供高精度航向、俯仰滾轉姿態與海拔遙測。",
    "ac.f1_t": "✈️ 全螢幕人工地平儀 (Artificial Horizon)",
    "ac.f1_d": "高對比度天地線與俯仰角/滾轉角刻度盤，支援全螢幕沉浸式飛行姿態顯示與零延遲感測器平滑濾波。",
    "ac.f2_t": "🧭 航空級精準數位羅盤",
    "ac.f2_d": "即時輸出真北/磁北航向角度、方位角讀數與磁場強度提示，輔助戶外導航與方位校準。",
    "ac.f3_t": "📡 GPS 與氣壓高度遙測",
    "ac.f3_d": "精確顯示當前經緯度座標、海拔高度、地面速度及網路輔助地理資訊，支援離線核心計算。",
    "ac.f4_t": "🌍 國際化多語言支援",
    "ac.f4_d": "內建即時多語言翻譯引擎，介面清爽專業、無廣告干擾，嚴格遵循 Google Play 隱私與安全規範。",
    "cat.all": "全部",
    "cat.sys": "系統工具",
    "cat.prod": "效率辦公",
    "app.pd_tag": "純淨極簡的裝置狀態儀表板、電池健康庫侖計監測與多尺寸桌面微件套件",
    "app.ac_tag": "航空級數位羅盤、全螢幕人工地平儀（姿態儀）與高精度地理/氣壓感測器遙測工具",
