    "app.title": "LubitSoft 官方應用中心 App (v2.0.0)",
    "app.desc": "Android 8.0+ · 19.10 MB · 一站式下載與自動更新提醒",
    "app.dl_btn": "⬇ 下載官方 App (APK)",
    "gp.beta_title": "Beta 嚐鮮階段提示",
    "gp.beta_desc": "Beta 嚐鮮階段尚未上傳 Google Play，敬請期待！目前您可透過官網直鏈或 LubitSoft 官方 App 直接下載正版 APK 安裝包。",
    "dino.sub": "彩色高清擬真版恐龍與載具橫版跑酷遊戲。涵蓋 7 大動態生態地圖、列車車頂跑酷、4 種角色與真實載具引擎音效、朝霞晚霞與雨雪天氣平滑過渡，支援橫豎屏無縫暢玩。",
    "dino.meta1": "版本：v1.4.0",
    "dino.meta2": "包名：com.dinohd.game",
    "dino.meta3": "系統要求：Android 7.0+ (API 24+)",
    "dino.meta4": "授權：免費正版 · 零廣告",
    "dino.dl_btn": "⬇ 官方直鏈 APK 下載 (3.29 MB)",
    "dino.desc": "Dino HD 傳承經典離線小恐龍跑酷核心手感，並採用原生 Kotlin 高幀率渲染引擎全面重製為彩色高清擬真畫面。遊戲內建 7 大生態地圖、晝夜朝霞晚霞與雨雪動態天氣平滑過渡、可跳上車頂奔跑的超長鐵路列車、4 種可選角色載具與真實物理合成音效，完全離線運行、零廣告干擾。",
    "dino.f1_t": "🌍 7 大擬真地圖與列車車頂跑酷",
    "dino.f1_d": "支援沙漠、溫帶現代城市、熱帶雨林、蘇聯雪地、北美沼澤、非洲草原（長頸鹿腿下穿行）與鐵路地圖（可跳上超長貨運集裝箱列車與高速客運列車車頂前進）。",
    "dino.f2_t": "🏍️ 4 種角色造型與真實載具音效",
    "dino.f2_d": "自由切換預設小恐龍、全避震山地自行車（真實塔基棘輪與鏈條聲）、450cc 越野摩托車（真實四衝程排氣聲浪與轟油門音效）及碳纖維彈跳鞋人物。",
    "dino.f3_t": "🌅 朝霞晚霞、2:1 晝夜與天氣平滑過渡",
    "dino.f3_d": "提供日出朝霞、正午晴空、日落晚霞、星夜彎月以及晴天、雨天、雪天連續插值平滑過渡，光影層次細膩真實。",
    "dino.f4_t": "🤖 智能軌跡自動模式、無敵模式與金幣錢包",
    "dino.f4_d": "內建拋物線軌跡預測 AI 自動遊玩模式、無敵穿障護盾、失敗原地復活、遊戲金幣錢包累積保存，並原生適配 11 國語言與橫豎屏無縫切換。",
    "dino.cl_v1_t": "v1.4.0 · 安裝包大小：3.29 MB",
    "dino.cl_v1_d": "新增鐵路地圖與超長貨運/客運列車車頂跑酷、現代城市與蘇聯雪地逆行渣土車；重做真實四衝程越野摩托車聲浪與山地自行車塔基棘輪音效；實現地圖與天氣平滑淡入淡出過渡與持久化金幣錢包。",
    "footer.l_pdino": "Dino HD 隱私權政策",
