    "priv.2048_title": "2048 隱私權政策 (Privacy Policy)",
    "priv.back_2048": "返回 2048 下載頁",
    "p2048.meta": "應用包名：com.lubitsoft.game2048 · 開發者：LubitSoft Inc. · 更新日期：2026-11-19",
    "p2048.h1": "1. 引言與適用範圍",
    "p2048.p1": "LubitSoft 高度重視使用者的隱私與資料安全。本隱私權政策適用於您透過 LubitSoft 官方網站、LubitSoft 官方應用中心 App 或其他官方管道下載並使用的 2048（包名：com.lubitsoft.game2048）Android 遊戲應用程式。",
    "p2048.h2": "2. 零敏感權限與純本地運行架構",
    "p2048.p2": "2048 嚴格遵循「零敏感權限、100% 本地運行、零隱私上傳」原則：",
    "p2048.li1": "零裝置敏感權限：本遊戲不申請相機、麥克風、位置資訊、通訊錄、電話狀態或外部儲存空間讀取等任何敏感權限。",
    "p2048.li2": "純本地遊戲存檔：您的目前棋盤進度、歷史最高分、對局歷史記錄、遊戲時長、音效與多語言設定均 100% 儲存在您裝置本地的應用沙盒（SharedPreferences）中，絕不上傳至任何外部伺服器。",
    "p2048.li3": "本地即時音效：遊戲內的輕敲音效均在裝置本地記憶體中即時合成播放，不讀取或存取您裝置上的任何個人媒體檔案。",
    "p2048.h3": "3. 零廣告與零第三方資料共享承諾",
    "p2048.li4": "2048 無需註冊或登入帳號，不收集姓名、電子郵件、裝置識別碼（IMEI / OAID / AAID）或任何個人身分資訊。",
    "p2048.li5": "本遊戲不包含任何第三方商業廣告 SDK、統計追蹤 SDK 或背景喚醒服務，絕不向任何第三方出售、出租或共享使用者資料。",
    "p2048.li6": "外部跳轉說明：僅當您在遊戲設定中主動點擊「公司官網 (lubitsoft.com)」或「問題回饋 (support@lubitsoft.com)」時，系統才會呼叫您裝置上的瀏覽器或郵件用戶端。",
    "p2048.h4": "4. 聯絡我們",
    "g2048.sub": "LubitSoft 匠心打造的經典數字益智遊戲。支援 4×4 至 8×8 多種棋盤、無盡模式與尊貴流光紫高階方塊、雙擬真點陣 LED 計時與滾動屏、Expectimax 智慧提示與最高 512 倍速自動通關，原生適配 12 種語言與全螢幕。",
    "g2048.meta1": "版本：v2.0.0",
    "g2048.meta2": "包名：com.lubitsoft.game2048",
    "g2048.meta3": "系統需求：Android 7.0+ (API 24+)",
    "g2048.meta4": "授權：免費正版 · 零廣告",
    "g2048.dl_btn": "⬇ 官方直鏈 APK 下載 (5.21 MB)",
    "g2048.desc": "2048 由 LubitSoft 原生打造，全面升級提供 4×4 至 8×8 五檔棋盤、無盡模式與 4096+ 分級流光紫羅蘭漸變方塊、雙路點陣 LED 顯示屏、完整歷史戰績記錄、統一質感輕敲音效與 12 種語言支援。",
    "g2048.f1_t": "🧩 4×4 至 8×8 多規格棋盤與無盡模式",
    "g2048.f1_d": "自由切換 4×4 至 8×8 棋盤，獨立保存進度與最高分；開啟無盡模式可突破 2048 衝擊 4096+ 流光紫高階方塊。",
    "g2048.f2_t": "🤖 Expectimax AI 智慧提示與 512 倍速託管",
    "g2048.f2_d": "提供最佳走法提示與理由，支援 1x–512x 與「擬真真人思考」速度自動通關。",
    "g2048.f3_t": "📟 雙路擬真低像素點陣 LED 顯示屏",
    "g2048.f3_d": "配備 99 天級綠色點陣計時器與橘黃色逐列步進滾動日期/星期/時間顯示屏，退出自動儲存並暫停計時。",
    "g2048.f4_t": "🏆 歷史戰績追蹤與 12 國語言支援",
    "g2048.f4_d": "點擊歷史最高分查看每局得分、用時、起止時間與 AI/提示使用次數；適配 12 種語言與統一輕敲音效。",
    "g2048.cl_v1_t": "v2.0.0 · 安裝包大小：5.21 MB",
    "g2048.cl_v1_d": "新增無盡模式與 4096+ 流光紫方塊、雙路點陣 LED 顯示屏、4×4–8×8 棋盤、歷史得分記錄、1x–512x 速度與 12 國語言。",
    "pdino.meta": "應用包名：com.dinohd.game · 開發者：LubitSoft Inc. · 更新日期：2026-11-19",
    "pdino.h1": "1. 引言與適用範圍",
    "pdino.p1": "LubitSoft 高度重視使用者的隱私與資料安全。本隱私權政策適用於您透過 LubitSoft 官方網站、LubitSoft 官方應用中心 App 或其他官方管道下載並使用的 Dino HD（包名：com.dinohd.game）Android 遊戲應用程式。",
    "pdino.h2": "2. 零敏感權限與純本機運行架構",
    "pdino.p2": "Dino HD 嚴格遵循「零敏感權限、100% 本機運行、零隱私上傳」原則：",
    "pdino.li1": "零裝置敏感權限：本遊戲不申請相機、麥克風、位置資訊、通訊錄、電話狀態或外部儲存讀取等任何敏感權限。",
    "pdino.li2": "純本機遊戲存檔：您的歷史最高積分（High Score）、遊戲錢包累積金幣（Coins）、角色載具選擇、螢幕方向、音效開關及多語言偏好均 100% 儲存在您裝置本機的應用沙盒（SharedPreferences）中，絕不上傳至任何外部伺服器。",
    "pdino.li3": "本機合成音效快取：遊戲內的恐龍、越野摩托車、山地自行車與彈跳鞋音效均在裝置本機臨時快取目錄（cacheDir）即時合成播放，不讀取或存取您裝置上的任何個人媒體檔案。",
    "pdino.h3": "3. 零廣告與零第三方資料共享承諾",
    "pdino.li4": "Dino HD 無需註冊或登入帳號，不收集姓名、信箱、裝置識別碼（IMEI / OAID / AAID）或任何個人身分資訊。",
    "pdino.li5": "本遊戲不包含任何第三方商業廣告 SDK、統計追蹤 SDK 或背景喚醒服務，絕不向任何第三方出售、出租或共享使用者資料。",
    "pdino.li6": "外部跳轉說明：僅當您在遊戲設定中主動點擊「官方網站 (lubitsoft.com)」或「回饋信箱 (support@lubitsoft.com)」時，系統才會呼叫您裝置上的瀏覽器或郵件用戶端。",
    "pdino.h4": "4. 聯繫我們",
    "priv.back_dino": "返回 Dino HD 下載頁",
