    "verify.slider_hint": "向右滑動完成驗證 →",
    "verify.manual_pass": "✓ 驗證成功，正在開始下載...",
    "lu.sub": "完全免費的 Windows 全能強力解除安裝、全軟體安裝根目錄識別與一鍵跨磁碟槽遷移工具，32/64 位元通用，內建 43 國語言。",
    "lu.meta1": "版本：v1.0.0",
    "lu.meta2": "系統需求：Windows 7 / 8 / 10 / 11 (32/64-bit)",
    "lu.meta3": "安裝包：LubitSoftUninstaller_Setup_v1.0.0.exe",
    "lu.meta4": "大小：4.27 MB",
    "lu.meta5": "授權：100% 免費軟體 · 零廣告無遙測",
    "lu.meta6": "內建語言：43 國語言（含多語言安裝程式）",
    "lu.dl_btn": "⬇ 免費下載安裝程式 (4.27 MB)",
    "lu.desc": "LubitSoft Uninstaller 是一款完全免費、零廣告、零遙測的 Windows 桌面軟體管理與強力解除安裝工具，單一程式通用相容 32/64 位元 Windows 7 / 8 / 10 / 11。具備全軟體安裝根目錄智慧識別、一鍵選擇目標磁碟槽自動無損遷移（NTFS 目錄聯結釋放 C 槽空間）、頑固軟體強力移除、深度殘留檔案與登錄檔清理、多軟體批次解除安裝、Microsoft Store（UWP）應用與啟動項管理，並完整內建 43 種語言。",
    "lu.f1_t": "📦 一鍵跨磁碟槽無損遷移",
    "lu.f1_d": "只需選擇目標磁碟槽（如 C: / D: / E:）即可自動完成軟體遷入並建立 NTFS 目錄聯結，免去繁瑣選資料夾，輕鬆釋放 C 槽空間且原程式無縫運作。",
    "lu.f2_t": "🗂️ 全軟體安裝根目錄智慧識別",
    "lu.f2_d": "十級探測引擎融合登錄檔、Steam 遊戲庫、MSI 元件、解除安裝路徑與目錄特徵，精準識別本機所有已安裝軟體的安裝根目錄。",
    "lu.f3_t": "🧹 強力移除與深度殘留清理",
    "lu.f3_d": "支援一般移除、頑固軟體強制清除、多軟體批次移除、Microsoft Store（UWP）應用與開機啟動項管理，自動深度掃描並徹底清理殘留目錄與登錄檔。",
    "lu.f4_t": "🌐 43 國語言全內建與多語言安裝包",
    "lu.f4_d": "軟體介面與 Inno 安裝程式均完整內建 43 國語言，自動適配系統語言，安裝時預設勾選建立桌面捷徑，開箱即用。",
    "lu.f5_t": "⚡ 32/64 位元合一通用單程式",
    "lu.f5_d": "單一檔案智慧適配 32 位元與 64 位元 Windows，自適應寬比例資訊列表完整呈現程式名稱、大小、安裝時間與安裝根目錄。",
    "lu.f6_t": "🛡️ 100% 免費、零廣告、零遙測",
    "lu.f6_d": "所有核心與進階功能完全免費開放，絕無彈窗廣告、絕無綑綁推廣、絕無後台聯網遙測，純粹本地高速運作。",
    "lu.sha_title": "🔐 官方安裝包 SHA-256 安全校驗",
    "lu.cl_v1_t": "v1.0.0（目前版本）· 安裝包大小：4.27 MB",
    "lu.cl_v1_d": "LubitSoft Uninstaller 首個正式版本發布：整合 32/64 位元通用單程式與 43 國語言 Inno 安裝程式（預設勾選桌面捷徑），提供一鍵跨磁碟槽無損遷移、全軟體安裝根目錄智慧識別、自適應寬比例列表、頑固軟體強力移除及深度殘留清理，所有功能 100% 免費。",
    "lapp.pill": "● LubitSoft 官方安卓用戶端",
    "lapp.sub": "LubitSoft 官方應用中心 Android 用戶端。手機端一站式取得公司全部官方安卓應用與遊戲、自動掃描官網上新與版本升級、SHA-256 簽章校驗、內建 11 國語言與離線隱私權政策查閱。",
    "lapp.meta1": "版本：v2.0.0",
    "lapp.meta2": "系統需求：Android 8.0+ (API 26+)",
    "lapp.meta3": "大小：19.10 MB",
    "lapp.meta4": "授權：免費正版 · 零廣告",
    "lapp.dl_btn": "⬇ 下載官方 App (v2.0.0 · 19.10 MB)",
    "lapp.desc": "LubitSoft App 採用原生 Kotlin 與 Jetpack Compose 打造，是 LubitSoft 官方行動端軟體生態中心。應用直連官方倉庫與網站原始碼，即時自動同步最新上架的 Android 應用、遊戲及 Windows 桌面軟體資訊，支援用戶端自身與已安裝應用自動檢測更新與通知提醒。",
    "lapp.f1_t": "🔄 全自動同步上新與自身更新",
    "lapp.f1_d": "開啟應用即自動掃描官網最新上架軟體與版本更新，同時支援檢測 LubitSoft App 自身新版本並一鍵線上升級。",
    "lapp.f2_t": "🛡️ SHA-256 校驗與網路偏好控制",
    "lapp.f2_d": "所有官方 APK 下載均自動校驗 SHA-256 簽章完整性，並支援設定僅 Wi-Fi 下載、任意網路或每次詢問。",
    "lapp.f3_t": "🌐 11 國語言全覆蓋與深淺色主題",
    "lapp.f3_d": "自動匹配手機系統語言，支援 11 種語言即時切換、跟隨系統/淺色/深色主題及 App 內查閱隱私權政策。",
    "lapp.f4_t": "💳 Windows 授權展示與官方付款通道",
    "lapp.f4_d": "同步展示桌面工具介紹與價格表，提供微信/支付寶官方收款與啟用碼申請指引。",
    "lapp.sha_title": "🔐 官方安裝包 SHA-256 安全校驗",
    "lapp.cl_v1_t": "v2.0.0 · 安裝包大小：19.10 MB",
    "lapp.cl_v1_d": "全面升級為動態倉庫同步架構，支援自動發現官網新上架應用與遊戲；新增開啟時自動掃描更新與 LubitSoft App 自身版本更新檢測。",
    "priv.lapp_title": "LubitSoft App 隱私權政策 (Privacy Policy)",
    "priv.back_lapp": "返回 LubitSoft App 詳情頁",
    "footer.l_plapp": "LubitSoft App 隱私權政策",
    "plapp.meta": "開發者：LubitSoft Inc. · 更新日期：2026-11-20",
    "plapp.h1": "1. 引言與適用範圍",
    "plapp.p1": "LubitSoft 高度重視使用者的隱私與裝置安全。本隱私權政策適用於 LubitSoft 官方應用中心 Android 用戶端（LubitSoft App）。",
    "plapp.h2": "2. 權限與本地資料處理",
    "plapp.p2": "LubitSoft App 遵循「最小必要權限、零個人資料收集」原則：",
    "plapp.li1": "網路存取權限（INTERNET / ACCESS_NETWORK_STATE）：用於同步官方軟體目錄、檢查版本更新、下載官方 APK 及判斷是否為 Wi-Fi 網路。",
    "plapp.li2": "安裝應用權限（REQUEST_INSTALL_PACKAGES）：僅在您主動點擊安裝或更新官方 APK 並通過 SHA-256 校驗後，用於啟動系統安裝程式。",
    "plapp.li3": "通知權限（POST_NOTIFICATIONS，可選）：僅用於在檢測到已安裝軟體或用戶端自身有新版本時發送更新提醒。",
    "plapp.li4": "已安裝應用查詢（QUERY_ALL_PACKAGES）：僅用於在裝置本地比對 LubitSoft 官方應用版本號，絕不收集或上傳任何其他應用列表。",
    "plapp.h3": "3. 零廣告與零資料共享承諾",
    "plapp.li5": "LubitSoft App 無需註冊或登入帳號，不收集姓名、手機號、信箱或任何廣告識別碼。",
    "plapp.li6": "本應用不含任何第三方商業廣告或行為追蹤 SDK，絕不出售、出租或共享任何使用者資料。",
    "plapp.h4": "4. 聯繫我們"
