    "pay.step_note": "Scan the QR code above in CNY (Monthly ¥3 / Quarterly ¥5 / Annual ¥10 / Lifetime ¥20). After payment, email the following 4 items to <strong>payment@lubitsoft.com</strong>:<br>1. Payment screenshot<br>2. Transaction ID<br>3. Purchased plan duration<br>4. Machine ID shown in the software<br>We will process your request and email your license key within <strong>24 hours</strong>.",
    "ppd.meta": "Package: com.weijielu.puredasher · Developer: LubitSoft Inc. · Updated: 2026-11-18",
    "ppd.h1": "1. Introduction & Scope",
    "ppd.p1": "LubitSoft values your privacy. This Privacy Policy applies to the PureDasher (com.weijielu.puredasher) Android application and its home screen widgets downloaded via Google Play or our official website.",
    "ppd.h2": "2. Permissions & Local Processing",
    "ppd.p2": "PureDasher operates on a local-first, minimal-permission, zero-upload principle:",
    "ppd.li1": "Network & Wi-Fi (INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE): Used locally to display network status and fetch optional language packs.",
    "ppd.li2": "Battery Monitoring (FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS): Used for local coulomb-counter battery health monitoring.",
    "ppd.li3": "Location (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION, Optional): Only used locally where Android requires location permission to read Wi-Fi info; never tracked or uploaded.",
    "ppd.li4": "Usage Stats (PACKAGE_USAGE_STATS, Optional): Shown locally only after explicit user consent.",
    "ppd.li5": "Notifications (POST_NOTIFICATIONS, Optional): Used for local battery status reminders.",
    "ppd.h3": "3. Storage & No Third-Party Sharing",
    "ppd.li6": "All hardware and battery diagnostics remain strictly on-device and are never sold or shared.",
    "ppd.li7": "Contains zero third-party ad SDKs.",
    "ppd.h4": "4. Contact Us",
    "pac.meta": "Package: com.weijielu.aircompass · Developer: LubitSoft Inc. · Updated: 2026-11-18",
    "pac.h1": "1. Introduction & Scope",
    "pac.p1": "LubitSoft respects your privacy and location security. This Privacy Policy explains how AirCompass (com.weijielu.aircompass) handles sensor and location data.",
    "pac.h2": "2. Sensors & Permissions",
    "pac.li1": "Location (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION): Used only while the app is active to display coordinates, altitude, speed, and magnetic declination; never tracked in the background or uploaded.",
    "pac.li2": "Motion & Environment Sensors: Magnetometer, accelerometer, gyroscope, and barometer data run 100% locally on-device.",
    "pac.li3": "Network (INTERNET / ACCESS_NETWORK_STATE): Used for network status and optional language lookups.",
    "pac.h3": "3. Zero Personal Collection & No Sharing",
    "pac.li4": "No account required; no personal identifiers or advertising IDs (AAID) collected.",
    "pac.li5": "We never sell, rent, or share user data.",
    "pac.h4": "4. Contact Us",
