    "hl.desc": "HardwareLens is a modern hardware inspection and real-time system monitoring tool built for Windows 10 and Windows 11. It features live CPU, RAM, Disk, and Network dashboards alongside deep diagnostics for GPU, Storage, Motherboard/BIOS, Audio, USB devices, and Battery health.",
