    "fu.dl_btn": "⬇ Download Installer (16.53 MB)",
    "fu.desc": "ForceUninstaller is a lightweight yet powerful uninstallation utility for Windows 10 and Windows 11. Single-app force uninstall and leftover/registry cleanup are free; Move to Another Drive and Batch Multi-App Uninstall are paid Pro features unlocked via a license key.",
