    "fu.f2_t": "🗂️ Deep Leftover & Registry Cleanup",
    "fu.f2_d": "Scans residual folders and Windows registry keys after uninstallation for one-click removal.",
    "fu.f3_t": "⚡ High-DPI Native UI",
    "fu.f3_d": "Crisp scaling on high-DPI monitors with seamless administrator elevation.",
    "fu.f4_t": "💎 Pro Paid Features",
    "fu.f4_d": "Move to Another Drive and Batch Multi-App Uninstall are paid in-app features unlocked with a license key.",
    "fu.paid_section_t": "Free & Paid Features",
    "fu.paid_section_desc": "Single-app force uninstallation and leftover cleanup are free. The following two advanced features require a paid license:",
    "fu.paid_f1_t": "📦 Move to Another Drive (Paid)",
    "fu.paid_f1_d": "Safely migrate installed applications to another disk partition to free up C: drive space without reinstalling.",
    "fu.paid_f2_t": "☑️ Batch Multi-App Uninstall (Paid)",
    "fu.paid_f2_d": "Select multiple programs to force-uninstall simultaneously while cleaning all residual files and registry entries.",
