    "pd.sub": "A clean, minimalist Android hardware dashboard, coulomb-counter battery health monitor, and 5-size home widget suite. Zero ads, zero bloat.",
    "pd.meta1": "Version: v2.1.0",
    "pd.meta2": "Package: com.weijielu.puredasher",
    "pd.meta3": "Requires: Android 8.0+ (API 26+)",
    "pd.meta4": "License: Free",
    "pd.dl_btn": "⬇ Direct APK Download (2.05 MB)",
    "pd.desc": "Built with native Kotlin and Jetpack Compose, PureDasher is designed for Android users who value clarity and control. It combines coulomb-counter battery health monitoring, a transparent permission center, and five home screen widgets—all processed locally.",
    "pd.f1_t": "🔋 Battery Health Monitor",
    "pd.f1_d": "Lightweight foreground service tracking charge/discharge current, temperature, and battery health with custom reminders.",
    "pd.f2_t": "🧩 5 Home Widget Sizes",
    "pd.f2_d": "Includes 2×1, 2×2, 4×1, 4×2, and 4×3 responsive widgets tailored to any home screen layout.",
    "pd.f3_t": "🛡️ Transparent Permissions",
    "pd.f3_d": "Clearly displays network, location, notification, and battery optimization status with one-tap system settings access.",
    "pd.f4_t": "🌐 Lightweight & Ad-Free",
    "pd.f4_d": "Supports instant language switching and Material 3 theming with zero third-party ad SDKs.",
    "ac.sub": "Avionics-inspired digital compass, full-screen Artificial Horizon, and real-time GPS / barometric telemetry for aviation and outdoor enthusiasts.",
    "ac.meta1": "Version: v2.2.0",
    "ac.meta2": "Package: com.weijielu.aircompass",
    "ac.meta3": "Requires: Android 8.0+ (API 26+)",
    "ac.meta4": "License: Free",
    "ac.dl_btn": "⬇ Direct APK Download (8.20 MB)",
    "ac.desc": "Inspired by modern aircraft Primary Flight Displays (PFD), AirCompass uses Jetpack Compose for smooth, high-contrast flight instrumentation, fusing magnetometer, accelerometer, gyroscope, barometer, and GPS sensors locally.",
    "ac.f1_t": "✈️ Full-Screen Artificial Horizon",
    "ac.f1_d": "High-contrast pitch and roll attitude indicator with smooth sensor fusion filtering.",
    "ac.f2_t": "🧭 Precision Digital Compass",
    "ac.f2_d": "Real-time True North / Magnetic North heading with magnetic declination support.",
    "ac.f3_t": "📡 GPS & Barometric Telemetry",
    "ac.f3_d": "Displays live coordinates, altitude, ground speed, and atmospheric pressure offline.",
    "ac.f4_t": "🌍 Multilingual Interface",
    "ac.f4_d": "Built-in real-time language switcher, clean UI, and strict Google Play privacy compliance.",
