    "gp.beta_desc": "Dino HD is currently in Beta and has not been uploaded to Google Play yet. Stay tuned! You can download the official signed APK directly from our website or via the LubitSoft Official App.",
    "dino.sub": "Full-color HD realistic dinosaur & vehicle side-scrolling runner. Features 7 dynamic biomes, train-roof parkour, 4 playable characters with realistic engine audio, sunrise/sunset & rain/snow transitions, and seamless portrait/landscape play.",
    "dino.meta1": "Version: v1.4.0",
    "dino.meta2": "Package: com.dinohd.game",
    "dino.meta3": "Requires: Android 7.0+ (API 24+)",
    "dino.meta4": "License: Free · Zero Ads",
    "dino.dl_btn": "⬇ Direct Official APK Download (3.29 MB)",
    "dino.desc": "Dino HD preserves the classic offline dino-runner feel while rebuilding everything in full-color HD using a native Kotlin high-FPS rendering engine. Includes 7 biomes, smooth day-night & weather transitions, long railway trains you can ride on top of, 4 vehicles/characters with synthesized physics audio, 100% offline & ad-free.",
    "dino.f1_t": "🌍 7 Realistic Biomes & Train-Roof Parkour",
    "dino.f1_d": "Explore Desert, Modern City, Tropical Rainforest, Soviet Snowfield, North American Swamp, African Savanna (duck under giraffes), and Railway (jump onto freight & high-speed train roofs).",
    "dino.f2_t": "🏍️ 4 Characters & Realistic Vehicle Audio",
    "dino.f2_d": "Switch between Classic Dino, Full-Suspension MTB (freehub ratchet & chain audio), 450cc Dirt Bike (4-stroke exhaust & throttle sound), and Carbon-Fiber Jump Shoes.",
    "dino.f3_t": "🌅 Smooth Dawn/Dusk, 2:1 Day-Night & Weather",
    "dino.f3_d": "Continuous smooth interpolation across sunrise, noon, sunset, starry night, clear skies, rain, and snow.",
    "dino.f4_t": "🤖 AI Auto-Play, Invincibility & Coin Wallet",
    "dino.f4_d": "Includes parabolic trajectory AI auto-play, invincibility shield, instant revive, persistent coin wallet, 11 languages, and seamless orientation switching.",
    "dino.cl_v1_t": "v1.4.0 · Size: 3.29 MB",
    "dino.cl_v1_d": "Added Railway biome with freight/passenger train-roof parkour and oncoming dump trucks; rebuilt 4-stroke dirt bike & MTB freehub audio; added smooth biome/weather crossfades and persistent coin wallet.",
    "footer.l_pdino": "Dino HD Privacy Policy",
    "priv.dino_title": "Dino HD Privacy Policy",
    "footer.l_p2048": "2048 Privacy Policy",
    "priv.2048_title": "2048 Privacy Policy",
    "priv.back_2048": "Back to 2048 Download Page",
    "p2048.meta": "Package: com.lubitsoft.game2048 · Developer: LubitSoft Inc. · Updated: 2026-11-19",
    "p2048.h1": "1. Introduction & Scope",
    "p2048.p1": "LubitSoft values your privacy and data security. This Privacy Policy applies to the 2048 Android game application (package: com.lubitsoft.game2048) downloaded from LubitSoft's official website, LubitSoftApp, or other official channels.",
    "p2048.h2": "2. Zero Sensitive Permissions & 100% Local Execution",
    "p2048.p2": "2048 strictly adheres to a zero-permission, 100% offline-first local architecture:",
    "p2048.li1": "Zero Sensitive Permissions: 2048 does not request camera, microphone, location, contacts, phone state, or external storage permissions.",
    "p2048.li2": "Local-Only Saves: Your board progress, high scores, match history, play duration, sound toggle, and language preferences are stored 100% locally in your device sandbox (SharedPreferences) and never uploaded to any server.",
    "p2048.li3": "Local Audio Synthesis: In-game tactile sound effects are synthesized in local memory without accessing any personal media files.",
    "p2048.h3": "3. Zero Ads & Zero Third-Party Data Sharing",
    "p2048.li4": "2048 requires no account registration and collects no names, emails, or device identifiers (IMEI / OAID / AAID).",
    "p2048.li5": "No third-party ad SDKs, analytics trackers, or background wake services are included. We never sell, rent, or share user data.",
    "p2048.li6": "External Links: Your browser or email client is only opened when you explicitly tap Official Website (lubitsoft.com) or Feedback (support@lubitsoft.com) in Settings.",
    "p2048.h4": "4. Contact Us",
    "g2048.sub": "Classic 2048 puzzle crafted by LubitSoft with 4×4–8×8 boards, Endless Mode with shimmering royal-purple 4096+ tiles, dual dot-matrix LED displays, Expectimax AI hints, and up to 512x Auto-Win across 12 languages.",
    "g2048.meta1": "Version: v2.0.0",
    "g2048.meta2": "Package: com.lubitsoft.game2048",
    "g2048.meta3": "Requires: Android 7.0+ (API 24+)",
    "g2048.meta4": "License: Free · Zero Ads",
    "g2048.dl_btn": "⬇ Download Official APK (5.21 MB)",
    "g2048.desc": "Natively crafted by LubitSoft, 2048 elevates the classic sliding puzzle with 4×4 to 8×8 boards, Endless Mode with shimmering purple 4096+ tiles, dual hardware-style dot-matrix LED displays (99-day timer + amber column-stepped date/weekday marquee), full Score History, unified tactile audio, and 12 languages.",
    "g2048.f1_t": "🧩 4×4–8×8 Boards & Endless Mode",
    "g2048.f1_d": "Switch freely between 4×4, 5×5, 6×6, 7×7, and 8×8 boards with independent saves, or enable Endless Mode to reach shimmering purple 4096+ tiles.",
    "g2048.f2_t": "🤖 Expectimax AI Hint & 512x Auto-Win",
    "g2048.f2_d": "Get instant best-move hints with reasons, or run Auto-Win from 1x up to 512x and Human-like thinking speed.",
    "g2048.f3_t": "📟 Dual Dot-Matrix LED Displays",
    "g2048.f3_d": "99-day green LED timer (synchronized blinking D & colons) plus an amber column-stepped scrolling date/weekday/time marquee with auto-pause on exit.",
    "g2048.f4_t": "🏆 Score History & 12 Languages",
    "g2048.f4_d": "Tap Best Score to inspect match duration, timestamps, mode, and AI/hint counts; supports 12 languages, display cutouts, and unified tactile audio.",
    "g2048.cl_v1_t": "v2.0.0 · Size: 5.21 MB",
    "g2048.cl_v1_d": "Added Endless Mode with shimmering purple 4096+ tiles, dual dot-matrix LED displays, 4×4–8×8 boards, Score History, 1x–512x & Human speeds, 12 languages, and unified tactile audio.",
    "pdino.meta": "Package: com.dinohd.game · Developer: LubitSoft Inc. · Updated: 2026-11-19",
    "pdino.h1": "1. Introduction & Scope",
    "pdino.p1": "LubitSoft values your privacy and data security. This Privacy Policy applies to the Dino HD Android game (package: com.dinohd.game) downloaded via lubitsoft.com, the LubitSoft Official App, or other official channels.",
    "pdino.h2": "2. Zero Sensitive Permissions & Local-Only Architecture",
    "pdino.p2": "Dino HD strictly follows a zero-sensitive-permission, 100% local, zero-upload design:",
    "pdino.li1": "Zero Sensitive Permissions: The game never requests camera, microphone, location, contacts, phone state, or external storage read permissions.",
    "pdino.li2": "Local-Only Save Data: High scores, coin wallet balance, selected vehicle/character, orientation, sound toggles, and language preferences are stored 100% locally in SharedPreferences and never uploaded.",
    "pdino.li3": "Local Synthesized Audio Cache: Sound effects are synthesized locally in the app cache directory (cacheDir) without accessing any personal media files.",
    "pdino.h3": "3. Zero Ads & Zero Third-Party Sharing",
    "pdino.li4": "No account registration is required, and no name, email, IMEI/OAID/AAID, or personal identifiers are collected.",
    "pdino.li5": "Contains no third-party ad SDKs, analytics trackers, or background wake services, and never sells or shares user data.",
    "pdino.li6": "External Links: Your browser or email client is only opened when you explicitly tap Official Website (lubitsoft.com) or Support Email (support@lubitsoft.com) in settings.",
    "pdino.h4": "4. Contact Us",
    "priv.back_dino": "Back to Dino HD",
