    "ppd.meta": "パッケージ：com.weijielu.puredasher · 開発：LubitSoft Inc. · 更新日：2026-11-18",
    "ppd.h1": "1. はじめに",
    "ppd.p1": "LubitSoftはお客様のプライバシーを尊重します。本ポリシーはPureDasher（com.weijielu.puredasher）アプリおよびウィジェットに適用されます。",
    "ppd.h2": "2. 権限とローカル処理",
    "ppd.p2": "PureDasherはローカル優先・最小権限・データ非送信を原則としています：",
    "ppd.li1": "ネットワーク・Wi-Fi（INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE）：接続状態の表示および言語パックの取得に使用します。",
    "ppd.li2": "バッテリー監視（FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS）：端末内でのバッテリー健康度計測に使用します。",
    "ppd.li3": "位置情報（ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION、任意）：Android仕様上Wi-Fi情報取得に必要な場合のみローカル使用し、追跡・送信は行いません。",
    "ppd.li4": "使用状況アクセス（PACKAGE_USAGE_STATS、任意）：明示的な許可後に端末内で統計表示を行います。",
    "ppd.li5": "通知（POST_NOTIFICATIONS、任意）：ローカルのバッテリー通知に使用します。",
    "ppd.h3": "3. データ保存と第三者提供の禁止",
    "ppd.li6": "すべての診断データは端末内にのみ保存され、第三者への販売・共有は一切行いません。",
    "ppd.li7": "第三者の広告SDKは一切含まれていません。",
    "ppd.h4": "4. お問い合わせ",
    "pac.meta": "パッケージ：com.weijielu.aircompass · 開発：LubitSoft Inc. · 更新日：2026-11-18",
