    "pac.p1": "LubitSoftは位置情報とプライバシー保護を重視しています。本ポリシーはAirCompass（com.weijielu.aircompass）に適用されます。",
    "pac.h2": "2. センサーと権限について",
    "pac.li1": "位置情報（ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION）：アプリ使用中の座標・高度・速度・磁気偏角表示のみに使用し、バックグラウンド追跡や送信は行いません。",
    "pac.li2": "モーション・環境センサー：磁気・加速度・ジャイロ・気圧センサーは100%端末内で処理されます。",
    "pac.li3": "ネットワーク（INTERNET / ACCESS_NETWORK_STATE）：接続確認および言語切り替えに使用します。",
