    "pd.dl_btn": "⬇ 公式 APK ダウンロード (2.05 MB)",
    "pd.desc": "KotlinとJetpack Composeで開発されたPureDasherは、バッテリーの充放電電流や健康度、端末権限を一目で把握できる軽量ツールです。すべてのデータは端末内でローカル処理されます。",
