    "dino.sub": "フルカラーHDのリアルな恐竜＆乗り物横スクロールランナー。7つのダイナミックバイオーム、列車の屋根パルクール、4種類のキャラとリアルなエンジン音、朝焼け・夕焼け・雨雪の滑らかな天候変化に対応。",
