    "dino.dl_btn": "⬇ 公式APKを直接ダウンロード (3.29 MB)",
    "dino.desc": "Dino HD は定番のオフライン恐竜ゲームの操作感をそのままに、Kotlin製高フレームレートエンジンでフルカラーHD化。7大マップ、列車屋根走行、4種類の乗り物・リアル合成サウンドを搭載し、完全オフライン・広告ゼロで楽しめます。",
    "dino.f1_t": "🌍 7つのリアルマップ＆列車屋根パルクール",
    "dino.f1_d": "砂漠、現代都市、熱帯雨林、雪原、沼地、サバンナ、鉄道マップを収録。長大な貨物・旅客列車の屋根を飛び移りながら走れます。",
    "dino.f2_t": "🏍️ 4種類のキャラ＆リアルな乗り物サウンド",
    "dino.f2_d": "恐竜、フルサスMTB（ラチェット＆チェーン音）、450cc オフロードバイク（4スト排気音）、カーボンジャンプシューズを切り替え可能。",
    "dino.f3_t": "🌅 朝焼け・夕焼け・昼夜と天候の滑らかな変化",
    "dino.f3_d": "日の出、昼、夕暮れ、星空、晴れ・雨・雪を連続補間で美しく表現します。",
