    "p2048.h1": "1. はじめに・適用範囲",
    "p2048.p1": "LubitSoft はユーザーのプライバシーとデータ保護を重視しています。本ポリシーは、LubitSoft 公式サイトや LubitSoftApp 等から提供される Android ゲーム「2048」（com.lubitsoft.game2048）に適用されます。",
    "p2048.h2": "2. 機密権限ゼロ＆完全ローカル動作",
    "p2048.p2": "2048 は「権限ゼロ・100% ローカル実行・外部送信ゼロ」を徹底しています：",
    "p2048.li1": "機密権限なし：カメラ、マイク、位置情報、連絡先、通話状態、外部ストレージ読み取り等の権限を一切要求しません。",
    "p2048.li2": "完全ローカル保存：盤面進行状況、ハイスコア、対戦履歴、プレイ時間、音声設定、言語設定は端末内のサンドボックス（SharedPreferences）にのみ保存され、外部サーバーへ送信されません。",
    "p2048.li3": "ローカル音声合成：効果音は端末メモリ上でリアルタイム生成され、個人のメディアファイルには一切アクセスしません。",
    "p2048.h3": "3. 広告ゼロ＆第三者共有ゼロ",
    "p2048.li4": "アカウント登録は不要で、氏名・メールアドレス・端末識別子（IMEI / OAID / AAID）を一切収集しません。",
    "p2048.li5": "第三者の広告 SDK やトラッキング SDK を一切含まず、ユーザーデータを販売・共有することはありません。",
    "p2048.li6": "外部リンク：設定画面で「公式サイト (lubitsoft.com)」または「フィードバック (support@lubitsoft.com)」をタップした場合のみ、ブラウザまたはメールアプリを起動します。",
    "p2048.h4": "4. お問い合わせ",
