    "g2048.desc": "4×4〜8×8 盤面、エンドレスモード（4096+ 紫グラデーションタイル）、99日タイマー＆アンバー色日付・曜日スクロール LED 表示、スコア履歴、統一効果音、12言語対応を搭載した次世代 2048。",
