    "lu.meta6": "対応言語：43 言語内蔵（多言語インストーラー対応）",
    "lu.dl_btn": "⬇ インストーラーを無料ダウンロード (4.27 MB)",
    "lu.desc": "LubitSoft Uninstaller は完全無料・無広告・無テレメトリの Windows ソフトウェア管理＆強力アンインストーラーです。単一の実行ファイルで 32/64 ビット版 Windows 7 / 8 / 10 / 11 に完全対応。全ソフトのインストールルート自動検出、移行先ドライブを選ぶだけのワンクリック無損失移行（NTFS ジャンクションで C ドライブ容量を解放）、頑固なアプリの強制削除、残留ファイルとレジストリの徹底掃除、複数一括削除、UWP・スタートアップ管理、43 言語をすべて無料で提供します。",
    "lu.f1_t": "📦 ワンクリック別ドライブ無損失移行",
    "lu.f1_d": "移行先ドライブ（C: / D: / E: など）を選ぶだけで自動移行し NTFS ジャンクションを作成。面倒なフォルダ選択なしで C ドライブ容量を安全に解放します。",
    "lu.f2_t": "🗂️ 全ソフトのインストールルート自動検出",
    "lu.f2_d": "レジストリ、Steam ライブラリ、MSI コンポーネント、アンインストーラー情報など 10 段階エンジンで、導入済み全ソフトのルートディレクトリを正確に特定します。",
    "lu.f3_t": "🧹 強力アンインストール＆徹底残留掃除",
    "lu.f3_d": "通常削除・頑固なアプリの強制削除・複数一括削除・Microsoft Store（UWP）＆スタートアップ管理に対応し、残留フォルダやレジストリを徹底除去します。",
    "lu.f4_t": "🌐 43 言語内蔵＆多言語インストーラー",
    "lu.f4_d": "アプリ本体と Inno インストーラーの双方が 43 言語を標準搭載。システム言語を自動認識し、デスクトップショートカット作成もデフォルト有効です。",
    "lu.f5_t": "⚡ 32/64 ビット統合・見やすい自動列幅",
    "lu.f5_d": "1つのバイナリで 32/64 ビット Windows に自動対応。最適化された列幅比率により、ソフト名・サイズ・導入日時・ルートパスを切れ目なく表示します。",
