    "ppd.meta": "패키지: com.weijielu.puredasher · 개발사: LubitSoft Inc. · 업데이트: 2026-11-18",
    "ppd.h1": "1. 소개 및 적용 범위",
    "ppd.p1": "LubitSoft는 사용자의 개인정보를 소중히 여깁니다. 본 방침은 PureDasher(com.weijielu.puredasher) Android 앱 및 위젯에 적용됩니다.",
    "ppd.h2": "2. 권한 및 로컬 데이터 처리",
    "ppd.p2": "PureDasher는 로컬 우선, 최소 권한, 외부 전송 금지 원칙을 준수합니다:",
    "ppd.li1": "네트워크 및 Wi-Fi(INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE): 로컬 네트워크 상태 표시 및 언어 팩 다운로드에 사용됩니다.",
    "ppd.li2": "배터리 모니터링(FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS): 기기 내 배터리 건강도 측정에 사용됩니다.",
    "ppd.li3": "위치 권한(ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION, 선택): Wi-Fi 정보 확인을 위해 OS가 요구할 때만 로컬로 사용되며 추적/전송하지 않습니다.",
    "ppd.li4": "앱 사용 통계(PACKAGE_USAGE_STATS, 선택): 사용자 동의 후 기기 내에서만 전력 통계를 표시합니다.",
    "ppd.li5": "알림(POST_NOTIFICATIONS, 선택): 로컬 배터리 알림 발송에 사용됩니다.",
    "ppd.h3": "3. 데이터 저장 및 제3자 공유 금지",
    "ppd.li6": "모든 진단 데이터는 기기 내부에만 저장되며 제3자에게 판매하거나 공유하지 않습니다.",
    "ppd.li7": "제3자 광고 SDK를 전혀 포함하지 않습니다.",
    "ppd.h4": "4. 문의하기",
    "pac.meta": "패키지: com.weijielu.aircompass · 개발사: LubitSoft Inc. · 업데이트: 2026-11-18",
    "pac.h1": "1. 소개 및 적용 범위",
    "pac.p1": "LubitSoft는 위치 정보와 개인정보 보호를 최우선으로 합니다. 본 방침은 AirCompass(com.weijielu.aircompass) 앱에 적용됩니다.",
    "pac.h2": "2. 센서 및 권한 안내",
    "pac.li1": "위치 권한(ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION): 앱 사용 중 좌표, 고도, 속도 및 자북 편각 계산에만 사용되며 백그라운드 추적이나 서버 전송을 하지 않습니다.",
    "pac.li2": "모션 및 환경 센서: 지자기, 가속도, 자이로, 기압 센서는 100% 기기 내에서 처리됩니다.",
    "pac.li3": "네트워크(INTERNET / ACCESS_NETWORK_STATE): 연결 상태 확인 및 언어 전환에 사용됩니다.",
    "pac.h3": "3. 개인정보 비수집 원칙",
    "pac.li4": "회원가입이 필요 없으며 개인 식별 정보나 광고 ID(AAID)를 수집하지 않습니다.",
    "pac.li5": "사용자 데이터를 절대 판매하거나 공유하지 않습니다.",
    "pac.h4": "4. 문의하기",
