    "hl.desc": "HardwareLens는 Windows 10 및 Windows 11을 위한 하드웨어 정보 검사 및 실시간 모니터링 도구입니다. CPU, 메모리, 디스크, 네트워크 대시보드와 함께 GPU, 저장장치, 메인보드 BIOS, 오디오, USB 및 배터리 상태를 정밀하게 확인하고 보고서를 내보낼 수 있습니다.",
