    "gp.beta_title": "베타 체험 안내",
    "gp.beta_desc": "Dino HD는 현재 베타 단계로 Google Play에 아직 등록되지 않았습니다. 공식 웹사이트 또는 LubitSoft 공식 앱에서 정품 서명 APK를 바로 다운로드하실 수 있습니다.",
    "dino.sub": "풀컬러 HD 리얼 공룡 & 탈것 횡스크롤 러너 게임. 7가지 다이내믹 맵, 기차 지붕 파쿠르, 4가지 캐릭터와 실제 엔진 사운드, 노을 및 눈비 날씨 전환을 지원합니다.",
