    "dino.dl_btn": "⬇ 공식 직링크 APK 다운로드 (3.29 MB)",
    "dino.desc": "Dino HD는 클래식 오프라인 공룡 게임의 손맛을 네이티브 Kotlin 고프레임 엔진으로 풀컬러 HD 리메이크했습니다. 7대 맵, 기차 지붕 달리기, 4종 탈것과 물리 합성 사운드를 광고 없이 완전 오프라인으로 즐길 수 있습니다.",
    "dino.f1_t": "🌍 7대 리얼 맵 & 기차 지붕 파쿠르",
    "dino.f1_d": "사막, 현대 도시, 열대우림, 설원, 늪지, 사바나 및 철도 맵(화물/여객 열차 지붕 점프 주행)을 지원합니다.",
    "dino.f2_t": "🏍️ 4종 캐릭터 & 실제 탈것 사운드",
