    "dino.f3_d": "일출, 정오, 일몰, 별밤과 맑음·비·눈 날씨가 부드럽게 보간 전환됩니다.",
    "dino.f4_t": "🤖 AI 자동 모드 · 무적 · 코인 지갑",
    "dino.f4_d": "포물선 궤적 예측 AI 자동 플레이, 무적 보호막, 부활, 영구 코인 지갑, 11개 언어 및 가로/세로 화면 전환을 지원합니다.",
    "dino.cl_v1_t": "v1.4.0 · 크기: 3.29 MB",
    "dino.cl_v1_d": "철도 맵 및 열차 지붕 파쿠르 추가, 4행정 바이크 및 MTB 사운드 재구축, 부드러운 맵·날씨 전환 및 영구 코인 지갑 구현.",
