    "priv.back_2048": "2048 다운로드 페이지로 돌아가기",
    "p2048.meta": "패키지: com.lubitsoft.game2048 · 개발: LubitSoft Inc. · 업데이트: 2026-11-19",
    "p2048.h1": "1. 개요 및 적용 범위",
    "p2048.p1": "LubitSoft는 사용자의 개인정보와 데이터 보안을 최우선으로 합니다. 본 방침은 LubitSoft 공식 웹사이트 및 LubitSoftApp을 통해 제공되는 Android 게임 2048(com.lubitsoft.game2048)에 적용됩니다.",
    "p2048.h2": "2. 민감 권한 제로 및 100% 로컬 실행",
    "p2048.p2": "2048은 민감 권한 없음, 100% 오프라인 로컬 저장 원칙을 준수합니다:",
    "p2048.li1": "민감 권한 미요구: 카메라, 마이크, 위치, 연락처, 전화 상태 또는 외부 저장소 접근 권한을 요청하지 않습니다.",
    "p2048.li2": "순수 로컬 저장: 게임 진행 상태, 최고 점수, 기록, 플레이 시간, 효과음 및 언어 설정은 기기 내 샌드박스(SharedPreferences)에만 저장되며 외부 서버로 전송되지 않습니다.",
    "p2048.li3": "로컬 사운드 합성: 효과음은 기기 메모리에서 실시간 합성되며 개인 미디어 파일에 접근하지 않습니다.",
    "p2048.h3": "3. 광고 없음 및 제3자 공유 금지",
    "p2048.li4": "회원가입이나 로그인이 필요 없으며 이름, 이메일, 기기 식별자(IMEI / OAID / AAID)를 수집하지 않습니다.",
    "p2048.li5": "제3자 광고 SDK나 추적 도구를 포함하지 않으며 사용자 데이터를 절대 판매하거나 공유하지 않습니다.",
    "p2048.li6": "외부 이동 안내: 설정에서 공식 웹사이트(lubitsoft.com) 또는 피드백(support@lubitsoft.com)을 직접 누른 경우에만 브라우저나 메일 앱이 실행됩니다.",
    "p2048.h4": "4. 문의하기",
    "g2048.sub": "LubitSoft가 제작한 클래식 2048 퍼즐. 4×4–8×8 보드, 무한 모드와 빛나는 보라색 4096+ 타일, 듀얼 도트 매트릭스 LED 디스플레이, Expectimax AI 힌트 및 최대 512배속 자동 클리어 지원.",
    "g2048.meta1": "버전: v2.0.0",
    "g2048.meta2": "패키지: com.lubitsoft.game2048",
    "g2048.meta3": "요구 사양: Android 7.0+ (API 24+)",
