    "g2048.dl_btn": "⬇ 공식 APK 다운로드 (5.21 MB)",
    "g2048.desc": "4×4–8×8 보드, 무한 모드(4096+ 보라색 그라데이션 타일), 99일 LED 타이머 및 주황색 스크롤 날짜/요일 LED, 점수 기록, 통일된 효과음, 12개 언어를 지원합니다.",
    "g2048.f1_t": "🧩 4×4–8×8 보드 및 무한 모드",
    "g2048.f1_d": "보드 크기별 독립 저장 및 무한 모드로 4096+ 보라색 타일에 도전하세요.",
    "g2048.f2_t": "🤖 Expectimax AI 힌트 및 512x 자동 클리어",
    "g2048.f2_d": "최적의 수 추천과 1x–512x 및 사람처럼 생각하는 속도의 자동 클리어를 제공합니다.",
    "g2048.f3_t": "📟 듀얼 도트 매트릭스 LED 디스플레이",
    "g2048.f3_d": "99일 녹색 LED 타이머와 열 단위 스크롤 날짜/요일/시간 LED를 탑재했습니다.",
    "g2048.f4_t": "🏆 점수 기록 및 12개 언어 지원",
    "g2048.f4_d": "최고 점수를 눌러 소요 시간, 시작/종료 시각, AI/힌트 횟수를 확인할 수 있습니다.",
    "g2048.cl_v1_t": "v2.0.0 · 크기: 5.21 MB",
    "g2048.cl_v1_d": "무한 모드, 4096+ 보라색 타일, 듀얼 LED 디스플레이, 4×4–8×8 보드, 점수 기록, 512x 속도, 12개 언어 추가.",
    "pdino.meta": "패키지: com.dinohd.game · 개발사: LubitSoft Inc. · 업데이트: 2026-11-19",
    "pdino.h1": "1. 개요 및 적용 범위",
    "pdino.p1": "LubitSoft는 사용자의 개인정보와 데이터 보안을 최우선으로 합니다. 본 방침은 공식 채널에서 다운로드한 Dino HD(com.dinohd.game)에 적용됩니다.",
    "pdino.h2": "2. 민감 권한 제로 & 100% 로컬 실행",
    "pdino.p2": "Dino HD는 '민감 권한 제로, 100% 로컬 실행, 데이터 업로드 제로' 원칙을 준수합니다:",
    "pdino.li1": "민감 권한 미요청: 카메라, 마이크, 위치, 연락처, 통화 상태, 외부 저장소 읽기 권한을 일절 요청하지 않습니다.",
    "pdino.li2": "로컬 전용 저장: 최고 점수, 코인 잔액, 캐릭터 선택 및 설정은 기기 내부(SharedPreferences)에만 저장되며 외부로 전송되지 않습니다.",
    "pdino.li3": "로컬 오디오 합성 캐시: 효과음은 앱 임시 캐시(cacheDir)에서 실시간 합성되며 개인 미디어 파일에 접근하지 않습니다.",
    "pdino.h3": "3. 광고 제로 & 제3자 공유 금지",
    "pdino.li4": "회원가입이나 로그인 없이 이용하며 이름, 이메일, 기기 식별자(IMEI/OAID/AAID)를 수집하지 않습니다.",
    "pdino.li5": "제3자 광고 SDK, 분석 추적 SDK 또는 백그라운드 서비스를 포함하지 않습니다.",
    "pdino.li6": "외부 링크 안내: 설정에서 공식 웹사이트나 지원 이메일을 직접 탭한 경우에만 브라우저 또는 메일 앱이 열립니다.",
    "pdino.h4": "4. 문의하기",
    "priv.back_dino": "Dino HD 페이지로 돌아가기",
