    "lu.sub": "100% 무료 Windows 강력 제거기, 전체 소프트웨어 설치 루트 자동 인식 및 원클릭 드라이브 마이그레이션 도구 (32/64비트 통합 · 43개 언어).",
    "lu.meta1": "버전: v1.0.0",
