    "lu.dl_btn": "⬇ 설치 프로그램 무료 다운로드 (4.27 MB)",
    "lu.desc": "LubitSoft Uninstaller는 광고와 원격 수집이 전혀 없는 100% 무료 Windows 소프트웨어 관리 및 강력 제거 도구로, 단일 실행 파일이 32/64비트 Windows 7 / 8 / 10 / 11을 모두 지원합니다. 10단계 지능형 설치 루트 탐지, 대상 드라이브 선택만으로 완료되는 원클릭 무손실 이동(NTFS 정션으로 C 드라이브 공간 확보), 완고한 프로그램 강제 제거, 잔여 폴더·레지스트리 심층 정리, 일괄 삭제, UWP·시작 프로그램 관리 및 43개 언어를 전면 무료 제공합니다.",
    "lu.f1_t": "📦 원클릭 드라이브 무손실 마이그레이션",
    "lu.f1_d": "대상 드라이브(C: / D: / E: 등)만 고르면 자동으로 안전하게 이동하고 NTFS 디렉터리 정션을 생성해 복잡한 폴더 선택 없이 C 드라이브 용량을 확보합니다.",
    "lu.f2_t": "🗂️ 전체 설치 루트 폴더 스마트 인식",
    "lu.f2_d": "레지스트리, Steam 게임 라이브러리, MSI 구성 요소, 제거 경로를 통합 분석하여 설치된 모든 프로그램의 루트 디렉터리를 정확히 찾아냅니다.",
    "lu.f3_t": "🧹 강력 제거 및 잔여 파일·레지스트리 심층 정리",
    "lu.f3_d": "일반·강제 제거, 다중 프로그램 일괄 삭제, Microsoft Store(UWP) 앱 및 시작 프로그램 관리와 함께 남은 폴더와 레지스트리 키를 깨끗이 정리합니다.",
    "lu.f4_t": "🌐 43개 언어 기본 내장 및 다국어 설치 마법사",
    "lu.f4_d": "프로그램 본체와 Inno 설치 관리자 모두 43개 언어를 완벽 지원하며 시스템 언어를 자동 인식하고 바탕 화면 바로가기 생성을 기본 선택합니다.",
    "lu.f5_t": "⚡ 32/64비트 통합 단일 실행 파일",
    "lu.f5_d": "단일 프로그램으로 32/64비트 Windows에 자동 대응하며 비례 열 너비 최적화로 앱 이름·크기·설치일·설치 루트 경로를 한눈에 보여줍니다.",
    "lu.f6_t": "🛡️ 100% 무료 · 무광고 · 무텔레메트리",
    "lu.f6_d": "모든 핵심 및 고급 기능을 조건 없이 무료 개방하며 팝업 광고, 번들 설치, 백그라운드 추적 없이 오직 로컬에서 초고속 동작합니다.",
    "lu.sha_title": "🔐 공식 설치 파일 SHA-256 보안 검증",
