    "lu.cl_v1_d": "LubitSoft Uninstaller 첫 정식 버전 출시: 32/64비트 통합 실행 파일과 43개 언어 Inno 설치 프로그램(바탕 화면 바로가기 기본 선택), 원클릭 드라이브 이동, 전체 설치 루트 자동 인식, 비례 열 너비 목록, 강제 제거 및 심층 잔여 정리를 100% 무료로 제공합니다.",
