    "ppd.meta": "Pakej: com.weijielu.puredasher · Pembangun: LubitSoft Inc. · Dikemas kini: 2026-11-18",
    "ppd.h1": "1. Pengenalan & Skop",
    "ppd.p1": "LubitSoft menghargai privasi anda. Dasar Privasi ini terpakai kepada aplikasi Android PureDasher (com.weijielu.puredasher) dan widget skrin utamanya.",
    "ppd.h2": "2. Kebenaran & Pemprosesan Tempatan",
    "ppd.p2": "PureDasher beroperasi berdasarkan prinsip setempat, kebenaran minimum dan sifar muat naik:",
    "ppd.li1": "Rangkaian & Wi-Fi (INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE): Digunakan secara setempat untuk memaparkan status rangkaian dan memuat turun pek bahasa.",
    "ppd.li2": "Pemantauan Bateri (FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS): Digunakan untuk pemantauan kesihatan bateri pada peranti.",
    "ppd.li3": "Lokasi (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION, Pilihan): Hanya digunakan secara setempat apabila Android memerlukannya untuk membaca info Wi-Fi; tidak pernah dijejak atau dimuat naik.",
    "ppd.li4": "Statistik Penggunaan (PACKAGE_USAGE_STATS, Pilihan): Dipaparkan secara setempat hanya selepas kebenaran pengguna.",
    "ppd.li5": "Pemberitahuan (POST_NOTIFICATIONS, Pilihan): Digunakan untuk peringatan status bateri setempat.",
    "ppd.h3": "3. Penyimpanan & Tiada Perkongsian Pihak Ketiga",
    "ppd.li6": "Semua diagnostik perkakasan dan bateri kekal pada peranti dan tidak pernah dijual atau dikongsi.",
    "ppd.li7": "Tiada SDK iklan pihak ketiga.",
    "ppd.h4": "4. Hubungi Kami",
    "pac.meta": "Pakej: com.weijielu.aircompass · Pembangun: LubitSoft Inc. · Dikemas kini: 2026-11-18",
    "pac.h1": "1. Pengenalan & Skop",
    "pac.p1": "LubitSoft menghormati privasi dan keselamatan lokasi anda. Dasar ini menerangkan bagaimana AirCompass (com.weijielu.aircompass) mengendalikan data sensor dan lokasi.",
    "pac.h2": "2. Sensor & Kebenaran",
    "pac.li1": "Lokasi (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION): Digunakan hanya semasa aplikasi aktif untuk memaparkan koordinat, altitud, kelajuan dan deklinasi magnetik; tidak pernah dijejak di latar belakang.",
    "pac.li2": "Sensor Pergerakan & Persekitaran: Magnetometer, akselerometer, giroskop dan barometer diproses 100% secara setempat.",
    "pac.li3": "Rangkaian (INTERNET / ACCESS_NETWORK_STATE): Digunakan untuk status rangkaian dan penukaran bahasa.",
    "pac.h3": "3. Sifar Pengumpulan Data Peribadi",
    "pac.li4": "Tiada akaun diperlukan; tiada pengecam peribadi atau AAID dikumpul.",
    "pac.li5": "Kami tidak pernah menjual atau berkongsi data pengguna.",
    "pac.h4": "4. Hubungi Kami",
