    "p2048.meta": "Pakej: com.lubitsoft.game2048 · Pembangun: LubitSoft Inc. · Dikemas kini: 2026-11-19",
    "p2048.h1": "1. Pengenalan & Skop",
    "p2048.p1": "LubitSoft mengutamakan privasi dan keselamatan data anda. Dasar Privasi ini terpakai untuk permainan Android 2048 (com.lubitsoft.game2048) yang dimuat turun daripada laman web rasmi LubitSoft atau LubitSoftApp.",
    "p2048.h2": "2. Tanpa Kebenaran Sensitif & Operasi Tempatan 100%",
    "p2048.p2": "2048 mematuhi prinsip tanpa kebenaran sensitif dan 100% luar talian:",
    "p2048.li1": "Tiada Kebenaran Sensitif: Tidak meminta akses kamera, mikrofon, lokasi, kenalan, atau storan luaran.",
    "p2048.li2": "Simpanan Tempatan Sahaja: Kemajuan papan, skor tertinggi, rekod perlawanan, masa bermain, bunyi dan bahasa disimpan 100% di peranti anda (SharedPreferences).",
    "p2048.li3": "Audio Tempatan: Kesan bunyi disintesis dalam memori peranti tanpa membaca fail media peribadi.",
    "p2048.h3": "3. Tanpa Iklan & Tanpa Perkongsian Data",
    "p2048.li4": "Tiada pendaftaran akaun diperlukan dan tiada pengumpulan nama, e-mel, atau pengecam peranti (IMEI / OAID / AAID).",
    "p2048.li5": "Tiada SDK iklan atau penjejak pihak ketiga. Kami tidak pernah menjual atau berkongsi data pengguna.",
    "p2048.li6": "Pautan Luaran: Pelayar atau aplikasi e-mel hanya dibuka apabila anda menekan Laman Web Rasmi atau Maklum Balas dalam Tetapan.",
    "p2048.h4": "4. Hubungi Kami",
    "g2048.sub": "Permainan teka-teki 2048 klasik oleh LubitSoft dengan papan 4×4–8×8, Mod Tanpa Had dengan jubin ungu 4096+, dwi-paparan LED matriks titik, petunjuk AI Expectimax & Auto hingga 512x.",
