    "lu.sub": "Penyahpasang paksa Windows 100% percuma dengan pengesanan direktori pemasangan menyeluruh & migrasi pemacu satu klik — universal 32/64-bit dengan 43 bahasa.",
    "lu.meta1": "Versi: v1.0.0",
    "lu.meta2": "Keperluan: Windows 7 / 8 / 10 / 11 (32/64-bit)",
    "lu.meta3": "Pemasang: LubitSoftUninstaller_Setup_v1.0.0.exe",
    "lu.meta4": "Saiz: 4.27 MB",
    "lu.meta5": "Lesen: 100% Percuma · Sifar Iklan & Telemetri",
    "lu.meta6": "Bahasa: 43 Bahasa Terbina (Aplikasi & Pemasang)",
    "lu.dl_btn": "⬇ Muat Turun Pemasang Percuma (4.27 MB)",
    "lu.desc": "LubitSoft Uninstaller ialah pengurus dan penyahpasang paksa perisian Windows yang percuma sepenuhnya, tanpa iklan dan tanpa telemetri dalam satu fail universal 32/64-bit untuk Windows 7 / 8 / 10 / 11. Ia menampilkan enjin pengesanan direktori akar 10 peringkat untuk semua program terpasang, migrasi pemacu satu klik melalui pautan NTFS lancar bagi melegakan ruang C:, nyahpasang paksa perisian degil, pembersihan sisa fail & registri mendalam, nyahpasang berkelompok, pengurusan UWP & permulaan serta 43 bahasa terbina.",
    "lu.f1_t": "📦 Migrasi Pemacu Satu Klik Tanpa Kehilangan",
    "lu.f1_d": "Hanya pilih pemacu sasaran (seperti C:, D:, E:) untuk memindahkan perisian secara automatik dengan sambungan NTFS lancar—tiada pilihan folder rumit, ruang C: segera lega.",
    "lu.f2_t": "🗂️ Pengesanan Direktori Akar Semua Perisian",
    "lu.f2_d": "Enjin 10 peringkat merentasi Registri, pustaka Steam, komponen MSI dan laluan pemasangan mengenal pasti direktori akar setiap aplikasi terpasang dengan tepat.",
    "lu.f3_t": "🧹 Nyahpasang Paksa & Pembersihan Sisa Mendalam",
    "lu.f3_d": "Menyokong nyahpasang biasa, buang paksa perisian degil, nyahpasang berkelompok, aplikasi Microsoft Store (UWP) & permulaan, serta pembersihan sisa folder dan registri.",
    "lu.f4_t": "🌐 43 Bahasa Terbina & Pemasang Pelbagai Bahasa",
