    "ppd.meta": "แพ็กเกจ: com.weijielu.puredasher · ผู้พัฒนา: LubitSoft Inc. · อัปเดต: 2026-11-18",
    "ppd.h1": "1. บทนำและขอบเขต",
    "ppd.p1": "LubitSoft ให้ความสำคัญกับความเป็นส่วนตัวของคุณ นโยบายนี้ใช้กับแอป PureDasher (com.weijielu.puredasher) และวิดเจ็ตบน Android",
    "ppd.h2": "2. สิทธิ์และการประมวลผลในเครื่อง",
    "ppd.p2": "PureDasher ยึดหลักการประมวลผลในเครื่อง ใช้สิทธิ์เท่าที่จำเป็น และไม่อัปโหลดข้อมูลส่วนตัว:",
    "ppd.li1": "เครือข่ายและ Wi-Fi (INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE): ใช้แสดงสถานะเครือข่ายในเครื่องและโหลดชุดภาษา",
    "ppd.li2": "การตรวจวัดแบตเตอรี่ (FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS): ใช้ตรวจวัดสุขภาพแบตเตอรี่ภายในเครื่อง",
    "ppd.li3": "ตำแหน่ง (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION, ตัวเลือก): ใช้ในเครื่องเฉพาะเมื่อระบบ Android ต้องการเพื่ออ่านข้อมูล Wi-Fi เท่านั้น ไม่มีการติดตามหรืออัปโหลด",
    "ppd.li4": "สถิติการใช้งาน (PACKAGE_USAGE_STATS, ตัวเลือก): แสดงในเครื่องเฉพาะเมื่อผู้ใช้ยินยอมเท่านั้น",
    "ppd.li5": "การแจ้งเตือน (POST_NOTIFICATIONS, ตัวเลือก): ใช้แจ้งเตือนสถานะแบตเตอรี่ในเครื่อง",
    "ppd.h3": "3. การจัดเก็บและไม่แบ่งปันข้อมูล",
    "ppd.li6": "ข้อมูลทั้งหมดเก็บไว้ในเครื่องของคุณเท่านั้น ไม่มีการขายหรือแบ่งปันให้บุคคลที่สาม",
    "ppd.li7": "ไม่มี SDK โฆษณาจากบุคคลที่สาม",
    "ppd.h4": "4. ติดต่อเรา",
    "pac.meta": "แพ็กเกจ: com.weijielu.aircompass · ผู้พัฒนา: LubitSoft Inc. · อัปเดต: 2026-11-18",
    "pac.h1": "1. บทนำและขอบเขต",
    "pac.p1": "LubitSoft เคารพความเป็นส่วนตัวและความปลอดภัยของตำแหน่งคุณ นโยบายนี้อธิบายการทำงานของ AirCompass (com.weijielu.aircompass)",
    "pac.h2": "2. เซ็นเซอร์และสิทธิ์",
    "pac.li1": "ตำแหน่ง (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION): ใช้เฉพาะขณะเปิดแอปเพื่อแสดงพิกัด ความสูง ความเร็ว และค่าความเบี่ยงเบนแม่เหล็ก ไม่มีการติดตามเบื้องหลังหรืออัปโหลด",
    "pac.li2": "เซ็นเซอร์การเคลื่อนไหวและสิ่งแวดล้อม: ประมวลผลในเครื่อง 100%",
    "pac.li3": "เครือข่าย (INTERNET / ACCESS_NETWORK_STATE): ใช้ตรวจสอบเครือข่ายและเปลี่ยนภาษา",
    "pac.h3": "3. ไม่เก็บข้อมูลส่วนบุคคล",
    "pac.li4": "ไม่ต้องลงทะเบียนบัญชี และไม่เก็บข้อมูลระบุตัวตนหรือ AAID",
    "pac.li5": "เราไม่เคยขายหรือแบ่งปันข้อมูลผู้ใช้",
    "pac.h4": "4. ติดต่อเรา",
