    "footer.l_p2048": "นโยบายความเป็นส่วนตัว 2048",
    "priv.2048_title": "นโยบายความเป็นส่วนตัว 2048",
    "priv.back_2048": "กลับไปหน้าดาวน์โหลด 2048",
    "p2048.meta": "แพ็กเกจ: com.lubitsoft.game2048 · ผู้พัฒนา: LubitSoft Inc. · อัปเดต: 2026-11-19",
    "p2048.h1": "1. บทนำและขอบเขต",
    "p2048.p1": "LubitSoft ให้ความสำคัญกับความเป็นส่วนตัวและความปลอดภัยของข้อมูล นโยบายนี้ใช้กับเกม Android 2048 (com.lubitsoft.game2048) จากเว็บไซต์ทางการของ LubitSoft หรือ LubitSoftApp",
    "p2048.h2": "2. ไม่ขอสิทธิ์ที่ละเอียดอ่อนและทำงานออฟไลน์ 100%",
    "p2048.p2": "2048 ปฏิบัติตามหลักการไม่ขอสิทธิ์และประมวลผลในเครื่อง 100%:",
    "p2048.li1": "ไม่มีสิทธิ์ที่ละเอียดอ่อน: ไม่ขอสิทธิ์กล้อง ไมโครโฟน ตำแหน่ง รายชื่อ หรือการอ่านไฟล์ภายนอก",
    "p2048.li2": "บันทึกข้อมูลในเครื่องเท่านั้น: ความคืบหน้า คะแนนสูงสุด ประวัติการเล่น เวลา เสียง และภาษาถูกเก็บไว้ในเครื่อง (SharedPreferences) เท่านั้น",
    "p2048.li3": "สังเคราะห์เสียงในเครื่อง: เอฟเฟกต์เสียงถูกสร้างในหน่วยความจำของเครื่องโดยไม่อ่านไฟล์สื่อส่วนตัว",
    "p2048.h3": "3. ไม่มีโฆษณาและไม่แชร์ข้อมูลกับบุคคลที่สาม",
    "p2048.li4": "ไม่ต้องสมัครสมาชิก และไม่เก็บชื่อ อีเมล หรือรหัสอุปกรณ์ (IMEI / OAID / AAID)",
    "p2048.li5": "ไม่มี SDK โฆษณาหรือการติดตามใดๆ และไม่ขายหรือแชร์ข้อมูลผู้ใช้",
    "p2048.li6": "ลิงก์ภายนอก: ระบบจะเปิดเบราว์เซอร์หรือแอปอีเมลเฉพาะเมื่อคุณกดปุ่มเว็บไซต์หรือส่งข้อเสนอแนะในการตั้งค่าเท่านั้น",
    "p2048.h4": "4. ติดต่อเรา",
    "g2048.sub": "เกมปริศนา 2048 คลาสสิกจาก LubitSoft รองรับกระดาน 4×4–8×8 โหมดไร้ขีดจำกัดพร้อมบล็อกสีม่วง 4096+ จอ LED ดอทเมทริกซ์คู่ และ AI อัตโนมัติสูงสุด 512x",
    "g2048.meta1": "เวอร์ชัน: v2.0.0",
