    "g2048.dl_btn": "⬇ ดาวน์โหลด APK ทางการ (5.21 MB)",
    "g2048.desc": "2048 จาก LubitSoft มาพร้อมกระดาน 4×4 ถึง 8×8 โหมดไร้ขีดจำกัด จอ LED ดอทเมทริกซ์คู่ ประวัติคะแนนละเอียด เสียงสัมผัสเดียว และรองรับ 12 ภาษา",
    "g2048.f1_t": "🧩 กระดาน 4×4–8×8 และโหมดไร้ขีดจำกัด",
    "g2048.f1_d": "สลับขนาดกระดานได้อิสระพร้อมบันทึกแยก และท้าทายบล็อกสีม่วงประกาย 4096+",
    "g2048.f2_t": "🤖 คำแนะนำ AI Expectimax และเล่นอัตโนมัติ 512x",
    "g2048.f2_d": "แนะนำตาเดินที่ดีที่สุดพร้อมเหตุผล และเล่นอัตโนมัติ 1x–512x หรือโหมดเสมือนคน",
    "g2048.f3_t": "📟 จอ LED ดอทเมทริกซ์คู่สมจริง",
    "g2048.f3_d": "ตัวจับเวลา LED สีเขียว 99 วัน และจอวันที่/วันในสัปดาห์/เวลาสีส้มเลื่อนทีละคอลัมน์",
    "g2048.f4_t": "🏆 ประวัติคะแนนและรองรับ 12 ภาษา",
    "g2048.f4_d": "แตะคะแนนสูงสุดเพื่อดูรายละเอียดเวลาเริ่ม-จบ โหมด และจำนวนครั้งที่ใช้ AI/คำใบ้",
    "g2048.cl_v1_t": "v2.0.0 · ขนาด: 5.21 MB",
    "g2048.cl_v1_d": "เพิ่มโหมดไร้ขีดจำกัด บล็อกม่วง 4096+ จอ LED คู่ กระดาน 4×4–8×8 ประวัติคะแนน ความเร็ว 512x และ 12 ภาษา",
    "pdino.meta": "แพ็กเกจ: com.dinohd.game · ผู้พัฒนา: LubitSoft Inc. · อัปเดต: 2026-11-19",
    "pdino.h1": "1. บทนำและขอบเขต",
    "pdino.p1": "LubitSoft ให้ความสำคัญกับความเป็นส่วนตัวของคุณ นโยบายนี้ใช้กับเกม Dino HD (com.dinohd.game) ที่ดาวน์โหลดผ่านช่องทางทางการ",
    "pdino.h2": "2. ไม่ขอสิทธิ์ละเอียดอ่อนและทำงานในเครื่อง 100%",
    "pdino.p2": "Dino HD ยึดหลักไม่ขอสิทธิ์ละเอียดอ่อน ทำงานในเครื่อง 100% และไม่อัปโหลดข้อมูล:",
    "pdino.li1": "ไม่ขอสิทธิ์ละเอียดอ่อน: ไม่ขอสิทธิ์กล้อง ไมโครโฟน ตำแหน่ง รายชื่อ สถานะโทรศัพท์ หรือไฟล์ภายนอก",
    "pdino.li2": "บันทึกข้อมูลในเครื่องเท่านั้น: คะแนนสูงสุด เหรียญ ตัวละคร และการตั้งค่าเก็บใน SharedPreferences เท่านั้น",
    "pdino.li3": "แคชเสียงสังเคราะห์ในเครื่อง: เสียงประกอบสร้างขึ้นใน cacheDir โดยไม่เข้าถึงไฟล์สื่อส่วนตัว",
    "pdino.h3": "3. ไร้โฆษณาและไม่แบ่งปันข้อมูล",
    "pdino.li4": "ไม่ต้องสมัครสมาชิก ไม่เก็บชื่อ อีเมล หรือรหัสอุปกรณ์ (IMEI/OAID/AAID)",
    "pdino.li5": "ไม่มี SDK โฆษณา ตัวติดตาม หรือบริการเบื้องหลัง",
    "pdino.li6": "ลิงก์ภายนอก: เปิดเบราว์เซอร์หรืออีเมลเฉพาะเมื่อคุณกดลิงก์เว็บไซต์หรืออีเมลสนับสนุนในการตั้งค่าเท่านั้น",
    "pdino.h4": "4. ติดต่อเรา",
    "priv.back_dino": "กลับไปหน้า Dino HD",
