    "lu.sub": "โปรแกรมถอนการติดตั้งแบบบังคับสำหรับ Windows ฟรี 100% ตรวจจับโฟลเดอร์ติดตั้งครบทุกโปรแกรม และย้ายข้ามไดรฟ์ในคลิกเดียว รองรับ 32/64 บิตและ 43 ภาษา",
    "lu.meta1": "เวอร์ชัน: v1.0.0",
    "lu.meta2": "ความต้องการระบบ: Windows 7 / 8 / 10 / 11 (32/64-bit)",
    "lu.meta3": "ไฟล์ติดตั้ง: LubitSoftUninstaller_Setup_v1.0.0.exe",
    "lu.meta4": "ขนาด: 4.27 MB",
    "lu.meta5": "สิทธิ์การใช้งาน: ฟรี 100% · ไร้โฆษณาและไร้การติดตาม",
    "lu.meta6": "ภาษาในตัว: 43 ภาษา (ทั้งตัวโปรแกรมและตัวติดตั้ง)",
    "lu.dl_btn": "⬇ ดาวน์โหลดตัวติดตั้งฟรี (4.27 MB)",
    "lu.desc": "LubitSoft Uninstaller คือโปรแกรมจัดการและถอนการติดตั้งซอฟต์แวร์บน Windows ที่ฟรี 100% ไร้โฆษณา ไร้การเก็บข้อมูล รวมรุ่น 32/64 บิตไว้ในไฟล์เดียวสำหรับ Windows 7 / 8 / 10 / 11 มาพร้อมระบบตรวจจับโฟลเดอร์ติดตั้งหลัก 10 ระดับสำหรับทุกโปรแกรม ย้ายโปรแกรมข้ามไดรฟ์อัตโนมัติในคลิกเดียวด้วย NTFS Junction เพื่อเพิ่มพื้นที่ไดรฟ์ C: ถอนการติดตั้งแบบบังคับ ล้างไฟล์ตกค้างและรีจิสทรีเชิงลึก ถอนหลายโปรแกรมพร้อมกัน จัดการแอป UWP และโปรแกรมเริ่มระบบ พร้อมรองรับ 43 ภาษา",
    "lu.f1_t": "📦 ย้ายโปรแกรมข้ามไดรฟ์ในคลิกเดียว",
    "lu.f1_d": "เพียงเลือกไดรฟ์ปลายทาง (เช่น C:, D:, E:) ระบบจะย้ายไฟล์และสร้าง NTFS Junction ให้อัตโนมัติ ไม่ต้องเลือกโฟลเดอร์ให้ยุ่งยาก เพิ่มพื้นที่ไดรฟ์ C: ได้ทันที",
    "lu.f2_t": "🗂️ ตรวจจับโฟลเดอร์ติดตั้งหลักครบทุกโปรแกรม",
    "lu.f2_d": "เอนจินตรวจจับ 10 ระดับครอบคลุมรีจิสทรี คลังเกม Steam องค์ประกอบ MSI และพาธติดตั้ง แสดงตำแหน่งโฟลเดอร์หลักของทุกโปรแกรมได้แม่นยำ",
    "lu.f3_t": "🧹 ถอนการติดตั้งแบบบังคับและล้างตกค้างเชิงลึก",
    "lu.f3_d": "รองรับทั้งการลบปกติ บังคับลบซอฟต์แวร์ลบยาก ถอนการติดตั้งพร้อมกันหลายตัว จัดการแอป Microsoft Store (UWP) และโปรแกรมเริ่มระบบ พร้อมกวาดล้างไฟล์และรีจิสทรีตกค้าง",
    "lu.f4_t": "🌐 รองรับ 43 ภาษาทั้งตัวโปรแกรมและตัวติดตั้ง",
    "lu.f4_d": "ทั้งซอฟต์แวร์และตัวติดตั้ง Inno รองรับครบทั้ง 43 ภาษา ตรวจจับภาษาระบบอัตโนมัติ และติ๊กสร้างทางลัดบนเดสก์ท็อปไว้เป็นค่าเริ่มต้น",
    "lu.f5_t": "⚡ รวม 32/64 บิตในไฟล์เดียวพร้อมตารางแสดงผลสมส่วน",
    "lu.f5_d": "ไฟล์เดียวใช้งานได้ทั้ง Windows 32 บิตและ 64 บิต จัดสัดส่วนคอลัมน์อัตโนมัติให้เห็นชื่อโปรแกรม ขนาด วันที่ติดตั้ง และโฟลเดอร์หลักครบถ้วน",
    "lu.f6_t": "🛡️ ฟรี 100% ไร้โฆษณา ไร้การส่งข้อมูล",
    "lu.f6_d": "เปิดให้ใช้งานครบทุกฟีเจอร์ฟรีโดยไม่มีโฆษณา ไม่มีโปรแกรมแถม และไม่มีการเก็บข้อมูลเบื้องหลัง ทำงานเร็วในเครื่องพร้อมค่าตรวจสอบ SHA-256 ทางการ",
    "lu.sha_title": "🔐 ค่าตรวจสอบความปลอดภัย SHA-256 ของตัวติดตั้งทางการ",
    "lu.cl_v1_t": "v1.0.0 (เวอร์ชันปัจจุบัน) · ขนาดตัวติดตั้ง: 4.27 MB",
    "lu.cl_v1_d": "เปิดตัว LubitSoft Uninstaller เวอร์ชันแรกอย่างเป็นทางการ: รวม 32/64 บิตในไฟล์เดียวพร้อมตัวติดตั้ง Inno 43 ภาษา (เลือกสร้างทางลัดเดสก์ท็อปอัตโนมัติ) ย้ายข้ามไดรฟ์ในคลิกเดียว ตรวจจับโฟลเดอร์หลักครบทุกแอป และล้างตกค้างเชิงลึก ฟรี 100%",
    "lapp.pill": "● แอป Android ทางการของ LubitSoft",
