    "pay.step_note": "Scannez le QR code ci-dessus en CNY, puis envoyez capture d'écran, numéro de transaction, durée choisie et code machine à <strong>payment@lubitsoft.com</strong>. Traitement sous <strong>24 heures</strong>.",
    "ppd.meta": "Paquet : com.weijielu.puredasher · Développeur : LubitSoft Inc. · Mis à jour : 2026-11-18",
    "ppd.h1": "1. Introduction et portée",
    "ppd.p1": "LubitSoft respecte votre vie privée. Cette politique s'applique à l'application Android PureDasher (com.weijielu.puredasher) et à ses widgets.",
    "ppd.h2": "2. Permissions et traitement local",
    "ppd.p2": "PureDasher fonctionne selon un principe local, avec un minimum de permissions et sans envoi de données :",
    "ppd.li1": "Réseau & Wi-Fi (INTERNET / ACCESS_NETWORK_STATE / ACCESS_WIFI_STATE) : Utilisé localement pour afficher l'état réseau et charger les langues.",
    "ppd.li2": "Surveillance batterie (FOREGROUND_SERVICE / REQUEST_IGNORE_BATTERY_OPTIMIZATIONS) : Utilisé pour mesurer l'état de la batterie localement.",
    "ppd.li3": "Localisation (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION, Optionnel) : Uniquement requis localement par Android pour lire les infos Wi-Fi ; jamais suivi ni envoyé.",
    "ppd.li4": "Statistiques d'utilisation (PACKAGE_USAGE_STATS, Optionnel) : Affiché localement uniquement après consentement explicite.",
    "ppd.li5": "Notifications (POST_NOTIFICATIONS, Optionnel) : Utilisé pour les alertes locales de batterie.",
    "ppd.h3": "3. Stockage et aucun partage",
    "ppd.li6": "Tous les diagnostics restent strictement sur votre appareil et ne sont jamais vendus ou partagés.",
    "ppd.li7": "Aucun SDK publicitaire tiers.",
    "ppd.h4": "4. Nous contacter",
    "pac.meta": "Paquet : com.weijielu.aircompass · Développeur : LubitSoft Inc. · Mis à jour : 2026-11-18",
    "pac.h1": "1. Introduction et portée",
    "pac.p1": "LubitSoft protège votre vie privée et vos données de localisation. Cette politique concerne AirCompass (com.weijielu.aircompass).",
    "pac.h2": "2. Capteurs et permissions",
    "pac.li1": "Localisation (ACCESS_FINE_LOCATION / ACCESS_COARSE_LOCATION) : Utilisée uniquement lorsque l'application est ouverte pour les coordonnées, l'altitude et la déclinaison magnétique ; jamais en arrière-plan.",
    "pac.li2": "Capteurs de mouvement et d'environnement : Magnétomètre, accéléromètre, gyroscope et baromètre traités 100% localement.",
    "pac.li3": "Réseau (INTERNET / ACCESS_NETWORK_STATE) : Utilisé pour l'état réseau et le changement de langue.",
    "pac.h3": "3. Zéro collecte personnelle",
    "pac.li4": "Aucun compte requis ; aucun identifiant personnel ni AAID collecté.",
    "pac.li5": "Nous ne vendons ni ne partageons aucune donnée utilisateur.",
    "pac.h4": "4. Nous contacter",
