function getCurrentLang() {
  const saved = localStorage.getItem("lubitsoft_lang");
  if (saved && LUBIT_I18N[saved]) return saved;
  const nav = (navigator.language || "zh-CN").toLowerCase();
  if (nav.startsWith("zh-tw") || nav.startsWith("zh-hk") || nav.startsWith("zh-hant")) return "zh-TW";
  if (nav.startsWith("zh")) return "zh-CN";
  const short = nav.split("-")[0];
  if (LUBIT_I18N[short]) return short;
  return "en";
}

function t(key) {
  const lang = getCurrentLang();
  return (LUBIT_I18N[lang] && LUBIT_I18N[lang][key]) || LUBIT_I18N["en"][key] || key;
}

function applyTranslations() {
  const lang = getCurrentLang();
  document.documentElement.lang = lang;

  document.querySelectorAll("[data-i18n]").forEach(el => {
    const key = el.getAttribute("data-i18n");
    const val = t(key);
    if (el.hasAttribute("data-i18n-html")) {
      el.innerHTML = val;
    } else {
      el.textContent = val;
    }
  });

  document.querySelectorAll("[data-i18n-ph]").forEach(el => {
    const key = el.getAttribute("data-i18n-ph");
    el.setAttribute("placeholder", t(key));
  });

  const btnLabel = document.getElementById("langDropdownLabel");
  if (btnLabel) btnLabel.textContent = `🌐 ${LUBIT_LANGS[lang] || lang}`;

  document.querySelectorAll("#langDropdownMenu .ui-dropdown-item").forEach(item => {
    item.classList.toggle("active", item.dataset.val === lang);
  });

  // Re-render dynamic catalogs, footer, theme dropdown & cookie banner
  if (typeof initFeaturedCatalog === "function") initFeaturedCatalog();
  const pageType = document.body.dataset.page;
  if ((pageType === "android" || pageType === "windows" || pageType === "ios" || pageType === "macos") && typeof initPlatformCatalog === "function") {
    initPlatformCatalog(pageType);
  }
  if (typeof renderUnifiedFooter === "function") renderUnifiedFooter();
  if (typeof updateThemeDropdownUI === "function") updateThemeDropdownUI();
  if (typeof updateCookieBannerText === "function") updateCookieBannerText();
}

function setLanguage(lang) {
  if (!LUBIT_I18N[lang]) return;
  localStorage.setItem("lubitsoft_lang", lang);
  if (typeof setSiteCookie === "function") setSiteCookie("lubitsoft_lang", lang, 365);
  applyTranslations();
}

function injectLangSwitcher() {
  const actions = document.querySelector(".nav-actions");
  if (!actions || document.getElementById("langDropdown")) return;

  const wrap = document.createElement("div");
  wrap.id = "langDropdown";
  wrap.className = "ui-dropdown";

  const lang = getCurrentLang();
  wrap.innerHTML = `
    <button type="button" class="ui-dropdown-btn" aria-label="Language">
      <span id="langDropdownLabel">🌐 ${LUBIT_LANGS[lang] || lang}</span>
      <span class="ui-dropdown-chevron">▾</span>
    </button>
    <div class="ui-dropdown-menu" id="langDropdownMenu">
      ${Object.entries(LUBIT_LANGS).map(([code, label]) => `
        <button type="button" class="ui-dropdown-item ${code === lang ? 'active' : ''}" data-val="${code}">
          <span>${label}</span>
          <span>${code === lang ? '✓' : ''}</span>
        </button>
      `).join("")}
    </div>
  `;

  const btn = wrap.querySelector(".ui-dropdown-btn");
  btn.addEventListener("click", e => {
    e.stopPropagation();
    document.querySelectorAll(".ui-dropdown.open").forEach(d => {
      if (d !== wrap) d.classList.remove("open");
    });
    wrap.classList.toggle("open");
  });

  wrap.querySelectorAll(".ui-dropdown-item").forEach(item => {
    item.addEventListener("click", () => {
      setLanguage(item.dataset.val);
      wrap.querySelectorAll(".ui-dropdown-item").forEach(i => {
        const isAct = i.dataset.val === item.dataset.val;
        i.classList.toggle("active", isAct);
        i.lastElementChild.textContent = isAct ? "✓" : "";
      });
      wrap.classList.remove("open");
    });
  });

  actions.prepend(wrap);
}

document.addEventListener("click", () => {
  document.querySelectorAll(".ui-dropdown.open").forEach(d => d.classList.remove("open"));
});

document.addEventListener("DOMContentLoaded", () => {
  injectLangSwitcher();
  applyTranslations();
});
